CREATE OR REPLACE FUNCTION private.staff_transfer_validate(actor bigint, src bigint, dst bigint)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  perform 1 from public.org_staff where id=actor and organization_id=1 and is_active is true and is_super_admin is true and deleted_at is null for share;
  if not found then raise exception using errcode='42501',message='Chỉ super admin đang hoạt động được chuyển quyền'; end if;
  if src=dst then raise exception using errcode='22023',message='Nhân viên nguồn và đích phải khác nhau'; end if;
  perform 1 from public.org_staff where id=dst and organization_id=1 and is_active is true and deleted_at is null for share;
  if not found then raise exception using errcode='22023',message='Nhân viên nhận không tồn tại hoặc đã bị khóa'; end if;
  if src is not null then
    perform 1 from public.org_staff where id=src and organization_id=1 and deleted_at is null for share;
    if not found then raise exception using errcode='22023',message='Không tìm thấy nhân viên nguồn'; end if;
  end if;
end $function$

CREATE OR REPLACE FUNCTION private.aka_agent_campaign_type_visibility(p_staff_id bigint, p_organization_id bigint, p_access jsonb, p_surface text, p_operation text, p_changes jsonb, p_include_catalog boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET statement_timeout TO '10s'
 SET lock_timeout TO '5s'
AS $function$
DECLARE
  v_staff public.org_staff%ROWTYPE;
  v_result jsonb;
  v_catalog jsonb;
BEGIN
  SELECT * INTO v_staff FROM public.org_staff
    WHERE id=p_staff_id AND organization_id=p_organization_id AND is_active=true AND deleted_at IS NULL;
  IF NOT FOUND OR NOT public.aka_agent_staff_time_allowed(p_staff_id) THEN RAISE EXCEPTION 'visibility_access_denied'; END IF;
  IF p_operation IS NULL OR p_operation NOT IN ('get','patch') OR p_surface NOT IN ('desktop','web')
    OR jsonb_typeof(p_access) IS DISTINCT FROM 'object' OR p_include_catalog IS NULL
  THEN RAISE EXCEPTION 'visibility_invalid_request'; END IF;
  IF p_operation='patch' THEN
    IF v_staff.is_admin IS DISTINCT FROM true THEN RAISE EXCEPTION 'visibility_access_denied'; END IF;
    IF jsonb_typeof(p_changes) IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'visibility_invalid_changes'; END IF;
    IF jsonb_array_length(p_changes) NOT BETWEEN 1 AND 1000 THEN RAISE EXCEPTION 'visibility_invalid_changes'; END IF;
    IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_changes) x WHERE jsonb_typeof(x)<>'object'
      OR jsonb_typeof(x->'actionId') IS DISTINCT FROM 'string' OR jsonb_typeof(x->'visible') IS DISTINCT FROM 'boolean'
      OR length(x->>'actionId')>100 OR (x->>'actionId') !~ '^[a-z][a-z0-9_]*$')
    THEN RAISE EXCEPTION 'visibility_invalid_changes'; END IF;
    IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_changes) x CROSS JOIN LATERAL jsonb_object_keys(x) k
      WHERE k NOT IN ('actionId','visible'))
      OR (SELECT count(DISTINCT x->>'actionId') FROM jsonb_array_elements(p_changes) x)<>jsonb_array_length(p_changes)
      OR EXISTS(SELECT 1 FROM jsonb_array_elements(p_changes) x WHERE NOT EXISTS(
        SELECT 1 FROM private.aka_agent_campaign_visibility_actions(p_access,p_surface) a WHERE a.id=x->>'actionId'))
    THEN RAISE EXCEPTION 'visibility_invalid_action'; END IF;
    INSERT INTO public.auto_campaign_type_visibility(organization_id) VALUES(p_organization_id) ON CONFLICT DO NOTHING;
    -- The UPDATE's row lock merges each patch against the latest committed array.
    UPDATE public.auto_campaign_type_visibility v SET hidden_action_ids=ARRAY(
      SELECT DISTINCT id FROM (
        SELECT unnest(v.hidden_action_ids) id
        UNION ALL SELECT x->>'actionId' FROM jsonb_array_elements(p_changes) x WHERE x->'visible'='false'::jsonb
      ) ids WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p_changes) x
        WHERE x->>'actionId'=ids.id AND x->'visible'='true'::jsonb) ORDER BY id
    ),revision=v.revision+1,updated_by=p_staff_id,updated_at=clock_timestamp()
    WHERE v.organization_id=p_organization_id;
  END IF;
  v_result:=private.aka_agent_campaign_visibility_snapshot(p_staff_id,p_organization_id);
  IF p_include_catalog THEN
    WITH actions AS MATERIALIZED (
      SELECT * FROM private.aka_agent_campaign_visibility_actions(p_access,p_surface)
    ), counts AS (
      SELECT c.action_id,count(*) n FROM public.auto_campaigns c
      JOIN actions act ON act.id=c.action_id
      JOIN public.auto_accounts a ON a.id=c.account_id AND a.staff_id=p_staff_id AND a.organization_id=p_organization_id
      WHERE c.staff_id=p_staff_id AND c.organization_id=p_organization_id AND c.is_delete=false
        AND (p_surface<>'web' OR a.flatform_type='sms' OR
          (a.flatform_type='zalo' AND a.is_zalo_show_web=false AND a.is_zalo_server=true))
        AND (p_surface<>'desktop' OR a.flatform_type<>'zalo'
          OR coalesce((p_access->>CASE WHEN a.is_zalo_show_web IS TRUE THEN 'web' WHEN a.is_zalo_server IS TRUE THEN 'server' ELSE 'qr' END)::boolean,false))
      GROUP BY c.action_id
    )
    SELECT coalesce(jsonb_agg(jsonb_build_object('id',a.id,'name',a.name,'platform',a.platform,
      'campaignCount',coalesce(c.n,0)) ORDER BY a.platform,a.id),'[]'::jsonb) INTO v_catalog
    FROM actions a LEFT JOIN counts c ON c.action_id=a.id;
    v_result:=v_result||jsonb_build_object('catalog',v_catalog);
  END IF;
  RETURN v_result;
END;
$function$

CREATE OR REPLACE FUNCTION private.validate_demo_care_manager_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_manager public.aka_customer%rowtype;
begin
  if tg_op = 'UPDATE' and new.demo_care_manager_customer_id is not distinct from old.demo_care_manager_customer_id then
    return new;
  end if;
  if tg_op = 'INSERT' and new.demo_care_manager_customer_id is null then return new; end if;
  -- Relationship writes go through the staff-authorized server, never public intake.
  if current_setting('role', true) in ('anon', 'authenticated') then
    raise exception 'demo_care_manager_server_only' using errcode = '42501';
  end if;
  if new.demo_care_manager_customer_id is null then return new; end if;
  perform pg_advisory_xact_lock(73422510, 1);
  if new.demo_care_manager_customer_id = new.id then
    raise exception 'demo_care_manager_self' using errcode = '23514';
  end if;
  select * into v_manager from public.aka_customer
    where id = new.demo_care_manager_customer_id for share;
  if not found or v_manager.merged_into_customer_id is not null
      or coalesce(v_manager.record_state, 'active') <> 'active' then
    raise exception 'demo_care_manager_unavailable' using errcode = '23514';
  end if;
  if v_manager.demo_care_manager_customer_id is not null
      or exists (select 1 from public.aka_customer where demo_care_manager_customer_id = new.id) then
    raise exception 'demo_care_manager_nested' using errcode = '23514';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.sql_account_aka_owner(p_account bigint, p_sql_staff bigint)
 RETURNS bigint
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare o public.aka_order; n bigint; owner_id bigint;
begin
  select count(*) into n from public.aka_order where account_id_old=p_account or (source_system='sql_account' and source_record_id=p_account);
  if n>1 then return null; end if;
  if n=1 then
    select * into o from public.aka_order where account_id_old=p_account or (source_system='sql_account' and source_record_id=p_account);
    o.staff_manage_id_old:=p_sql_staff;
    return (private.aka_order_owner_state(o)->>'ownerId')::bigint;
  end if;
  select count(*),min(id) into n,owner_id from public.org_staff where organization_id=1 and sql_staff_id=p_sql_staff and deleted_at is null;
  return case when n=1 then owner_id else null end;
end $function$

CREATE OR REPLACE FUNCTION private.guard_demo_care_crm_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if new.crm_type_id not in (1, 2, 3, 5, 7, 9, 10, 11) then return new; end if;
  -- Serialize the final insert with relationship edits, including callers that bypass preflight.
  perform 1 from public.aka_customer where id = new.customer_id for share;
  if public.demo_care_should_skip_v1(new.customer_id, new.crm_type_id, new.demo_date, new.source_order_id) then
    -- Raising prevents downstream code from treating a zero-row insert as success or notifying Lark.
    raise exception 'demo_care_managed_customer' using errcode = 'P0001';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.aka_crm_log_crm_delete()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_ctx jsonb;
  v_role text;
  v_app text;
  v_limit constant integer := 2000;
  v_total bigint;
begin
  begin
    v_ctx := private.aka_crm_log_ctx();
    v_role := coalesce(nullif(pg_catalog.current_setting('request.jwt.claims', true), '')::jsonb ->> 'role', session_user::text);
    v_app := nullif(pg_catalog.current_setting('application_name', true), '');
    select pg_catalog.count(*) into v_total from old_rows;

    insert into public.aka_crm_log_change
      (request_id, actor_type, actor_key, org_staff_id, sql_staff_id, organization_id, source,
       db_source, table_name, record_pk, operation, old_data)
    select (v_ctx ->> 'request_id')::uuid,
           coalesce(v_ctx ->> 'actor_type', 'system'),
           coalesce(v_ctx ->> 'actor_key', 'db:' || v_role),
           (v_ctx ->> 'org_staff_id')::bigint, (v_ctx ->> 'sql_staff_id')::bigint, (v_ctx ->> 'organization_id')::bigint,
           coalesce(v_ctx ->> 'source', 'db' || coalesce(':' || v_app, '')),
           'supabase', 'aka_crm', o.id::text, 'delete',
           private.aka_crm_log_row(pg_catalog.to_jsonb(o), array['updated_at']::text[], '{}'::text[])
    from (select * from old_rows order by id limit v_limit) as o;

    -- Xoá hàng loạt vượt trần: thêm 1 dòng tóm tắt số lượng.
    if v_total > v_limit then
      insert into public.aka_crm_log_change
        (request_id, actor_type, actor_key, org_staff_id, sql_staff_id, organization_id, source,
         db_source, table_name, record_pk, operation, new_data)
      values ((v_ctx ->> 'request_id')::uuid, coalesce(v_ctx ->> 'actor_type', 'system'),
              coalesce(v_ctx ->> 'actor_key', 'db:' || v_role),
              (v_ctx ->> 'org_staff_id')::bigint, (v_ctx ->> 'sql_staff_id')::bigint, (v_ctx ->> 'organization_id')::bigint,
              coalesce(v_ctx ->> 'source', 'db' || coalesce(':' || v_app, '')), 'supabase', 'aka_crm', '*', 'summary',
              pg_catalog.jsonb_build_object('thao_tac', 'delete', 'so_dong', v_total, 'da_ghi_chi_tiet', v_limit));
    end if;
  exception when others then
    raise warning 'aka_crm_log: không ghi được nhật ký xoá aka_crm: %', sqlerrm;
  end;
  return null;
end
$function$

CREATE OR REPLACE FUNCTION private.capture_crm_product_transition()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  t jsonb := new.gen_meta -> 'product_transition';
  prior jsonb := old.gen_meta -> 'product_transition';
  fields jsonb;
  registry jsonb;
  source_owner bigint;
  source_account bigint;
  source_org_product bigint;
  kind text;
  source_id bigint;
begin
  if prior is not null and t is distinct from prior then
    raise exception 'product_transition_immutable' using errcode = '23514';
  end if;
  if t is null or t = 'null'::jsonb or t is not distinct from prior then return new; end if;
  if current_user not in ('postgres', 'service_role', 'supabase_admin') then
    raise exception 'product_transition_backend_only' using errcode = '42501';
  end if;
  if new.purchase_date is null or new.cskh_completed_date is null or new.customer_id is null
     or jsonb_typeof(t) <> 'object'
     or (t->>'customer_id')::bigint is distinct from new.customer_id
     or (t->>'crm_id')::bigint is distinct from new.id
     or (t->>'confirmed_by')::bigint is distinct from new.org_staff_updated_id
     or t->'destination_product_ids' is distinct from to_jsonb(new.purchase_product_ids)
     or coalesce(jsonb_array_length(t->'destination_product_ids'), 0) = 0
     or coalesce(t->>'expiration_date', '') !~ '^\d{4}-\d{2}-\d{2}$'
     or coalesce(t->>'confirmed_at', '') = '' then
    raise exception 'product_transition_invalid' using errcode = '23514';
  end if;
  kind := t->>'source_kind';
  source_id := (t->>'source_id')::bigint;
  if (t->>'key') is distinct from kind || ':' || source_id || ':' || (t->>'expiration_date') then
    raise exception 'product_transition_invalid_key' using errcode = '23514';
  end if;
  if kind = 'aka_order' then
    select o.customer_id, o.account_id_old into source_owner, source_account
      from public.aka_order o where o.id = source_id and o.source_system = 'sql_account'
        and (o.date_expiration at time zone 'UTC')::date = (t->>'expiration_date')::date for share;
    if source_account is null or source_account is distinct from (t->>'sql_account_id')::bigint then
      raise exception 'product_transition_source_changed' using errcode = '23514';
    end if;
  elsif kind = 'org_product' then
    select o.customer_id, p.id into source_owner, source_org_product
      from public.org_organization_product p join public.org_organization o on o.id = p.organization_id
      where p.id = source_id and coalesce(p.is_deleted, false) = false
        and (p.expiration_date at time zone 'Asia/Ho_Chi_Minh')::date = (t->>'expiration_date')::date for share of p, o;
    if source_org_product is distinct from (t->>'org_product_id')::bigint then
      raise exception 'product_transition_source_changed' using errcode = '23514';
    end if;
  else
    raise exception 'product_transition_invalid_source' using errcode = '23514';
  end if;
  if source_owner is distinct from new.customer_id then
    raise exception 'product_transition_wrong_customer' using errcode = '23514';
  end if;
  -- Row lock serializes this merge with other custom_fields writers that use CAS.
  select coalesce(c.custom_fields, '{}'::jsonb) into fields from public.aka_customer c
    where c.id = new.customer_id for update;
  if not found or jsonb_typeof(fields) <> 'object' then
    raise exception 'product_transition_customer_unavailable' using errcode = '23514';
  end if;
  registry := coalesce(fields->'product_transitions', '{}'::jsonb);
  if jsonb_typeof(registry) <> 'object' then
    raise exception 'product_transition_registry_invalid' using errcode = '23514';
  end if;
  if registry ? (t->>'key') and registry->(t->>'key') is distinct from t then
    raise exception 'product_transition_already_confirmed' using errcode = '23514';
  end if;
  update public.aka_customer set custom_fields = jsonb_set(fields, '{product_transitions}', registry || jsonb_build_object(t->>'key', t)),
    updated_at = clock_timestamp() where id = new.customer_id;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.crm_product_transition_reason(fields jsonb, source_order bigint, account_id bigint, org_product bigint, expiration date)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare registry jsonb := fields->'product_transitions'; t jsonb;
begin
  if registry is null then return null; end if;
  if jsonb_typeof(registry) <> 'object' then return 'product_transition_review'; end if;
  if registry = '{}'::jsonb then return null; end if;
  if source_order is null and account_id is null and org_product is null then return 'product_transition_review'; end if;
  for t in select value from jsonb_each(registry) loop
    if coalesce(t->>'source_kind','') not in ('aka_order','org_product') or coalesce(t->>'source_id','') !~ '^[1-9][0-9]*$'
       or coalesce(t->>'expiration_date','') !~ '^\d{4}-\d{2}-\d{2}$' then return 'product_transition_review'; end if;
    if ((t->>'source_kind' = 'aka_order' and (t->>'source_id')::bigint = source_order)
       or (t->>'sql_account_id')::bigint = account_id or (t->>'org_product_id')::bigint = org_product) then
      if expiration is null then return 'product_transition_review'; end if;
      if expiration <= (t->>'expiration_date')::date then return 'product_transition_replaced'; end if;
    end if;
  end loop;
  return null;
exception when invalid_text_representation or datetime_field_overflow then return 'product_transition_review';
end;
$function$

CREATE OR REPLACE FUNCTION private.guard_crm_product_transition()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  fields jsonb;
  o public.aka_order%rowtype;
  account_id bigint := new.sql_account_id;
  org_product bigint := new.org_organization_product_id;
  expiration date := new.source_expiration_date;
  reason text;
  resolved_source_order bigint := new.source_order_id;
  match_count integer;
  product_owner bigint;
begin
  if new.cskh_completed_date is not null or
     not (coalesce(new.crm_type_id in (3,4,16,17,18,23), false) or
       coalesce(new.crm_type_id = 15 and new.source_type = 'cskh_activity_near_expiry', false)) then return new; end if;
  select c.custom_fields into fields from public.aka_customer c where c.id = new.customer_id for share;
  if not found then raise exception 'product_transition_review' using errcode = '23514'; end if;
  if fields->'product_transitions' is null then return new; end if;
  if resolved_source_order is null and account_id is not null then
    select count(*), min(id) into match_count, resolved_source_order from public.aka_order
      where customer_id = new.customer_id and source_system = 'sql_account' and account_id_old = account_id;
    if match_count <> 1 then raise exception 'product_transition_review' using errcode = '23514'; end if;
  end if;
  if resolved_source_order is not null then
    select * into o from public.aka_order where id = resolved_source_order;
    if not found or o.customer_id is distinct from new.customer_id then
      raise exception 'product_transition_review' using errcode = '23514';
    end if;
    if o.source_system = 'sql_account' then
      if account_id is not null and account_id is distinct from o.account_id_old then
        raise exception 'product_transition_review' using errcode = '23514';
      end if;
      account_id := o.account_id_old;
      expiration := coalesce(expiration, (o.date_expiration at time zone 'UTC')::date);
    elsif o.source_system = 'org_product' then
      if org_product is not null and org_product is distinct from o.org_organization_product_id then
        raise exception 'product_transition_review' using errcode = '23514';
      end if;
      org_product := o.org_organization_product_id;
      expiration := coalesce(expiration, (o.date_expiration at time zone 'Asia/Ho_Chi_Minh')::date);
    end if;
  end if;
  if org_product is not null then
    select org.customer_id, coalesce(expiration, (p.expiration_date at time zone 'Asia/Ho_Chi_Minh')::date)
      into product_owner, expiration from public.org_organization_product p
      join public.org_organization org on org.id = p.organization_id where p.id = org_product;
    if not found or product_owner is distinct from new.customer_id then
      raise exception 'product_transition_review' using errcode = '23514';
    end if;
  end if;
  reason := private.crm_product_transition_reason(fields, resolved_source_order, account_id, org_product, expiration);
  if reason is not null then raise exception '%', reason using errcode = '23514'; end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.validate_ai_form_config()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
  IF EXISTS (SELECT 1 FROM unnest(NEW.campaign_action_ids) a(id)
    LEFT JOIN public.auto_campaign_actions c ON c.id=a.id
    WHERE c.id IS NULL OR c.is_delete IS TRUE) THEN
    RAISE EXCEPTION 'Unknown campaign action in AI configuration' USING ERRCODE='23514';
  END IF;
  IF cardinality(NEW.campaign_action_ids) <> (SELECT count(DISTINCT id) FROM unnest(NEW.campaign_action_ids) a(id)) THEN
    RAISE EXCEPTION 'Duplicate campaign action in AI configuration' USING ERRCODE='23514';
  END IF;
  IF EXISTS (SELECT 1 FROM public.ai_model WHERE id=NEW.model_id AND organization_id IS NOT NULL) THEN
    RAISE EXCEPTION 'Form AI requires a global model' USING ERRCODE='23514';
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION private.capture_aka_crm_call_delay_alert()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_call_created_at timestamptz;
  v_delay interval;
  v_delay_seconds bigint;
  v_delay_level text;
  v_level_message text;
  v_staff_name text := '';
  v_customer_phone text;
  v_pancake_link text := '';
  v_contact_conversion_id text;
  v_webhook_url text;
  v_webhook_payload jsonb;
  v_webhook_status text;
  v_webhook_request_id bigint;
  v_webhook_error_sqlstate text;
  v_alert_id bigint;
begin
  -- The WHEN clause is repeated defensively because this is privileged code.
  if old.cskh_completed_date is not null
     or new.cskh_completed_date is null
     or new.crm_type_id not in (1, 2)
     or new.aka_call_id is null then
    return new;
  end if;

  select call_row.created_at
  into v_call_created_at
  from public.aka_call as call_row
  where call_row.id = new.aka_call_id;

  if not found then
    return new;
  end if;

  v_delay := v_call_created_at - new.created_at;

  -- Compare the exact interval first. Persisting whole seconds is only for
  -- display/audit; flooring must never promote 09:59.999 into the next band.
  if v_delay < interval '5 minutes' then
    return new;
  end if;

  v_delay_seconds := pg_catalog.floor(
    extract(epoch from v_delay)
  )::bigint;

  if v_delay < interval '10 minutes' then
    v_delay_level := 'late_5_10';
    v_level_message :=
      'Bạn gọi điện trễ khách hàng này, yêu cầu gọi ngay khi có khách hàng mới.';
  elsif v_delay < interval '20 minutes' then
    v_delay_level := 'late_10_20';
    v_level_message := 'Bạn gọi cho khách hàng này quá trễ.';
  else
    v_delay_level := 'severe_20_plus';
    v_level_message := 'Lỗi nghiêm trọng — gọi quá trễ.';
  end if;

  select coalesce(
    nullif(pg_catalog.btrim(staff.name_akabiz), ''),
    nullif(pg_catalog.btrim(staff.name), ''),
    nullif(pg_catalog.btrim(staff.username), ''),
    ''
  )
  into v_staff_name
  from public.org_staff as staff
  where staff.id = new.org_staff_updated_id;

  v_staff_name := coalesce(v_staff_name, '');

  if new.customer_id is not null then
    select nullif(pg_catalog.btrim(customer.phone), '')
    into v_customer_phone
    from public.aka_customer as customer
    where customer.id = new.customer_id;
  end if;

  v_customer_phone := coalesce(
    v_customer_phone,
    nullif(pg_catalog.btrim(new.customer_phone), ''),
    ''
  );

  -- Only forward a direct HTTPS Pancake conversation URL. Reject aggregate
  -- multi-page links and embedded second URLs. If the CRM snapshot is unsafe,
  -- derive a canonical URL from a contact explicitly linked to this customer.
  if pg_catalog.btrim(coalesce(new.pancake_url, ''))
       ~* '^https://([[:alnum:]-]+[.])*pancake[.]vn/[^[:space:]]*[?&]c_id=[^&[:space:]]+'
     and pg_catalog.btrim(new.pancake_url) !~* 'multi_pages'
     and pg_catalog.strpos(
       pg_catalog.lower(
         pg_catalog.substr(pg_catalog.btrim(new.pancake_url), 9)
       ),
       'https://'
     ) = 0 then
    v_pancake_link := pg_catalog.btrim(new.pancake_url);
  elsif new.customer_id is not null then
    select pg_catalog.btrim(contact.conversion_id)
    into v_contact_conversion_id
    from public.contacts as contact
    where contact.customer_id = new.customer_id
      and contact.conversion_id is not null
      and (
        pg_catalog.btrim(contact.conversion_id)
          ~ '^pzl_[ug]_[0-9]+_[[:alnum:]_-]+$'
        or pg_catalog.btrim(contact.conversion_id) ~ '^[0-9]+_[0-9]+$'
      )
    order by contact.last_message_at desc nulls last, contact.id desc
    limit 1;

    if v_contact_conversion_id ~ '^pzl_[ug]_([0-9]+)_[[:alnum:]_-]+$' then
      v_pancake_link := pg_catalog.format(
        'https://pancake.vn/pzl_%s?c_id=%s',
        (pg_catalog.regexp_match(
          v_contact_conversion_id,
          '^pzl_[ug]_([0-9]+)_[[:alnum:]_-]+$'
        ))[1],
        v_contact_conversion_id
      );
    elsif v_contact_conversion_id ~ '^([0-9]+)_[0-9]+$' then
      v_pancake_link := pg_catalog.format(
        'https://pancake.vn/%s?c_id=%s',
        (pg_catalog.regexp_match(
          v_contact_conversion_id,
          '^([0-9]+)_[0-9]+$'
        ))[1],
        v_contact_conversion_id
      );
    end if;
  end if;

  v_webhook_payload := pg_catalog.jsonb_build_object(
    'staff_name', v_staff_name,
    'loai_loi', 'Trễ call khách hàng mới',
    'mo_ta_loi', pg_catalog.format(
      '%s Trễ %s phút %s giây. SĐT: %s. CRM tạo: %s. Cuộc gọi: %s.',
      v_level_message,
      v_delay_seconds / 60,
      v_delay_seconds % 60,
      v_customer_phone,
      pg_catalog.to_char(
        new.created_at at time zone 'Asia/Ho_Chi_Minh',
        'DD/MM/YYYY HH24:MI:SS'
      ),
      pg_catalog.to_char(
        v_call_created_at at time zone 'Asia/Ho_Chi_Minh',
        'DD/MM/YYYY HH24:MI:SS'
      )
    ),
    'link_pancake', coalesce(v_pancake_link, '')
  );

  begin
    select nullif(pg_catalog.btrim(secret.decrypted_secret), '')
    into v_webhook_url
    from vault.decrypted_secrets as secret
    where secret.name = 'crm_call_delay_lark_webhook_url'
    order by secret.updated_at desc nulls last, secret.id desc
    limit 1;
  exception
    when others then
      v_webhook_error_sqlstate := sqlstate;
      v_webhook_url := null;
  end;

  if v_webhook_url is null then
    v_webhook_status := 'missing_config';
    v_webhook_error_sqlstate := coalesce(v_webhook_error_sqlstate, '02000');
  elsif v_webhook_url !~
      '^https://akagroup[.]sg[.]larksuite[.]com/base/workflow/webhook/event/[A-Za-z0-9_-]+/?$' then
    v_webhook_status := 'missing_config';
    v_webhook_error_sqlstate := '22023';
    v_webhook_url := null;
  else
    -- Insert first and only enqueue when this completion event won the unique
    -- key. The immediate status update is invisible outside this transaction,
    -- so the durable audit remains append-only and duplicate requests cannot be
    -- queued by a retried trigger invocation.
    insert into public.aka_crm_call_delay_alert (
      crm_id_snapshot,
      aka_call_id,
      crm_type_id_snapshot,
      actor_org_staff_id_snapshot,
      staff_name_snapshot,
      customer_phone_snapshot,
      crm_created_at,
      call_created_at,
      completion_at,
      delay_seconds,
      delay_level,
      webhook_status
    )
    values (
      new.id,
      new.aka_call_id,
      new.crm_type_id,
      new.org_staff_updated_id,
      v_staff_name,
      v_customer_phone,
      new.created_at,
      v_call_created_at,
      new.cskh_completed_date,
      v_delay_seconds,
      v_delay_level,
      'enqueue_failed'
    )
    on conflict (crm_id_snapshot, completion_at, aka_call_id) do nothing
    returning id into v_alert_id;

    if v_alert_id is null then
      return new;
    end if;

    begin
      select net.http_post(
        url := v_webhook_url,
        body := v_webhook_payload,
        headers := '{"Content-Type":"application/json"}'::jsonb,
        timeout_milliseconds := 8000
      )
      into v_webhook_request_id;

      if v_webhook_request_id is null then
        v_webhook_status := 'enqueue_failed';
        v_webhook_error_sqlstate := 'P0001';
      else
        v_webhook_status := 'queued';
        v_webhook_error_sqlstate := null;
      end if;
    exception
      when others then
        v_webhook_status := 'enqueue_failed';
        v_webhook_request_id := null;
        v_webhook_error_sqlstate := sqlstate;
    end;

    update public.aka_crm_call_delay_alert as alert
    set
      webhook_status = v_webhook_status,
      webhook_request_id = v_webhook_request_id,
      webhook_error_sqlstate = v_webhook_error_sqlstate
    where alert.id = v_alert_id;

    return new;
  end if;

  insert into public.aka_crm_call_delay_alert (
    crm_id_snapshot,
    aka_call_id,
    crm_type_id_snapshot,
    actor_org_staff_id_snapshot,
    staff_name_snapshot,
    customer_phone_snapshot,
    crm_created_at,
    call_created_at,
    completion_at,
    delay_seconds,
    delay_level,
    webhook_status,
    webhook_error_sqlstate
  )
  values (
    new.id,
    new.aka_call_id,
    new.crm_type_id,
    new.org_staff_updated_id,
    v_staff_name,
    v_customer_phone,
    new.created_at,
    v_call_created_at,
    new.cskh_completed_date,
    v_delay_seconds,
    v_delay_level,
    v_webhook_status,
    v_webhook_error_sqlstate
  )
  on conflict (crm_id_snapshot, completion_at, aka_call_id) do nothing;

  return new;
exception
  when others then
    -- A CRM completion is authoritative. Unexpected audit/configuration issues
    -- are fail-open, and no URL, payload, token or message content is logged.
    raise warning
      'crm_call_delay_alert_capture_failed crm_id=% aka_call_id=% sqlstate=%',
      new.id,
      new.aka_call_id,
      sqlstate;
    return new;
end
$function$

CREATE OR REPLACE FUNCTION private.trg_sync_aka_crm_customer_lifecycle()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_customer_ids bigint[];
begin
  if tg_op = 'DELETE' then
    v_customer_ids := private.invalidate_aka_customer_lifecycle_source(
      'aka_crm',
      old.id
    );
    perform private.refresh_aka_customer_lifecycle_projections(v_customer_ids);
    return old;
  end if;

  v_customer_ids := private.sync_aka_crm_customer_lifecycle(new);
  perform private.refresh_aka_customer_lifecycle_projections(v_customer_ids);
  return new;
end
$function$

CREATE OR REPLACE FUNCTION private.sync_aka_order_history_customer_lifecycle(p_history aka_order_history)
 RETURNS bigint[]
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_customer_ids bigint[];
  v_customer_id bigint;
  v_customer_text text;
  v_order_found boolean := false;
  v_before_demo boolean;
  v_after_demo boolean;
  v_before_paid boolean;
  v_after_paid boolean;
  v_trial_before timestamptz;
  v_trial_after timestamptz;
  v_purchase_before timestamptz;
  v_purchase_after timestamptz;
  v_actor_sql_staff_id bigint;
  v_after_deleted boolean;
  v_org_staff_id bigint;
  v_staff_quality text;
  v_source_changed_at timestamptz;
  v_is_domain_sale boolean;
begin
  if p_history.id is null then
    return '{}'::bigint[];
  end if;

  v_customer_ids := private.invalidate_aka_customer_lifecycle_source(
    'aka_order_history',
    p_history.id
  );

  if not coalesce(
       p_history.outcome = any (array[
         'committed', 'recorded', 'reconciled', 'compensated'
       ]::text[]),
       false
     )
     or p_history.operation in ('DELETE', 'BASELINE')
     or p_history.primary_event_type = 'migration_baseline'
     or not coalesce(
       p_history.source_system = any (
         array['sql_account', 'legacy_manual']::text[]
       ),
       false
     ) then
    return v_customer_ids;
  end if;

  if p_history.aka_order_id is not null then
    select coalesce(order_row.customer_id, organization.customer_id)
    into v_customer_id
    from public.aka_order as order_row
    left join public.org_organization as organization
      on organization.id = order_row.organization_id
    where order_row.id = p_history.aka_order_id;
    v_order_found := found;
  end if;

  if not v_order_found then
    v_customer_text := coalesce(
      p_history.order_after_snapshot #>> '{order,customer_id}',
      p_history.order_before_snapshot #>> '{order,customer_id}'
    );
    if v_customer_text ~ '^[1-9][0-9]*$' then
      v_customer_id := v_customer_text::bigint;
    end if;
  end if;

  if not v_order_found
     and v_customer_id is null
     and p_history.organization_id is not null then
    select organization.customer_id
    into v_customer_id
    from public.org_organization as organization
    where organization.id = p_history.organization_id;
  end if;

  if v_customer_id is null then
    return v_customer_ids;
  end if;

  v_actor_sql_staff_id := case
    when p_history.operation = 'INSERT'
      and p_history.order_after_snapshot
          #>> '{order,staff_create_id_old}' ~ '^[1-9][0-9]*$'
      then (
        p_history.order_after_snapshot
          #>> '{order,staff_create_id_old}'
      )::bigint
    else p_history.actor_sql_staff_id
  end;

  v_org_staff_id := private.resolve_lifecycle_org_staff_id(
    p_history.actor_org_staff_id,
    v_actor_sql_staff_id,
    null
  );
  v_staff_quality := private.lifecycle_staff_quality(
    v_org_staff_id,
    p_history.actor_org_staff_id,
    v_actor_sql_staff_id,
    null
  );
  v_source_changed_at := coalesce(
    p_history.changed_at,
    p_history.recorded_at,
    pg_catalog.statement_timestamp()
  );

  v_before_demo := coalesce(p_history.entitlement_state_before = 'trial', false)
    or private.lifecycle_package_is_demo(
      p_history.package_type_before,
      p_history.package_name_before,
      false
    )
    or coalesce(
      pg_catalog.lower(
        p_history.order_before_snapshot #>> '{order,is_demo}'
      ) = 'true',
      false
    );
  v_after_demo := coalesce(p_history.entitlement_state_after = 'trial', false)
    or private.lifecycle_package_is_demo(
      p_history.package_type_after,
      p_history.package_name_after,
      false
    )
    or coalesce(
      pg_catalog.lower(
        p_history.order_after_snapshot #>> '{order,is_demo}'
      ) = 'true',
      false
    );

  v_trial_before := nullif(
    p_history.order_before_snapshot #>> '{order,trial_start_date}',
    ''
  )::timestamptz;
  v_trial_after := nullif(
    p_history.order_after_snapshot #>> '{order,trial_start_date}',
    ''
  )::timestamptz;
  v_after_deleted := coalesce(
    pg_catalog.lower(
      p_history.order_after_snapshot #>> '{order,is_deleted}'
    ) = 'true',
    false
  );

  if v_after_demo
     and not v_after_deleted
     and (
    not v_before_demo
    or (
      v_trial_after is not null
      and v_trial_after is distinct from v_trial_before
    )
    or p_history.operation = 'INSERT'
    or p_history.primary_event_type = 'trial_started'
  ) then
    perform private.upsert_aka_customer_lifecycle_event(
      v_customer_id,
      'demo',
      coalesce(
        v_trial_after,
        p_history.source_effective_at,
        p_history.changed_at
      ),
      v_org_staff_id,
      'aka_order_history',
      p_history.id,
      'demo',
      case when v_trial_after is not null
        then 'exact' else 'inferred' end,
      v_staff_quality,
      10,
      v_source_changed_at
    );
  end if;

  -- entitlement_state may call a positive amount "paid" even while is_paid is
  -- false, so only the explicit payment flag is accepted here.
  v_before_paid := coalesce(
      pg_catalog.lower(p_history.pricing_before ->> 'is_paid') = 'true',
      false
    )
    or coalesce(
      pg_catalog.lower(
        p_history.order_before_snapshot #>> '{order,is_paid}'
      ) = 'true',
      false
    );
  v_after_paid := coalesce(
      pg_catalog.lower(p_history.pricing_after ->> 'is_paid') = 'true',
      false
    )
    or coalesce(
      pg_catalog.lower(
        p_history.order_after_snapshot #>> '{order,is_paid}'
      ) = 'true',
      false
    );
  v_purchase_before := coalesce(
    p_history.purchase_date_before,
    nullif(
      p_history.order_before_snapshot #>> '{order,purchase_date}',
      ''
    )::timestamptz
  );
  v_purchase_after := coalesce(
    p_history.purchase_date_after,
    nullif(
      p_history.order_after_snapshot #>> '{order,purchase_date}',
      ''
    )::timestamptz
  );
  v_is_domain_sale := p_history.primary_event_type = any (array[
    'subscription_purchased',
    'subscription_created',
    'subscription_upgraded',
    'subscription_renewed',
    'purchase_completed',
    'payment_committed',
    'payment_reconciled',
    'sale_completed'
  ]::text[]);

  if v_after_paid
     and not v_after_demo
     and not v_after_deleted
     and (
    not v_before_paid
    or (
      v_purchase_after is not null
      and v_purchase_after is distinct from v_purchase_before
    )
    or p_history.operation = 'INSERT'
    or v_is_domain_sale
  ) then
    perform private.upsert_aka_customer_lifecycle_event(
      v_customer_id,
      'sale',
      coalesce(
        v_purchase_after,
        p_history.source_effective_at,
        p_history.changed_at
      ),
      v_org_staff_id,
      'aka_order_history',
      p_history.id,
      'sale',
      case when v_purchase_after is not null
        then 'exact' else 'inferred' end,
      v_staff_quality,
      10,
      v_source_changed_at
    );
  end if;

  return coalesce(v_customer_ids, '{}'::bigint[])
    || array[v_customer_id]::bigint[];
end
$function$

CREATE OR REPLACE FUNCTION private.capture_aka_crm_completed_by_org_staff()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if tg_op = 'INSERT' then
    new.completed_by_org_staff_id := case
      when new.cskh_completed_date is null then null
      else private.resolve_lifecycle_org_staff_id(
        new.org_staff_updated_id,
        null,
        null
      )
    end;
    return new;
  end if;

  if new.cskh_completed_date is null then
    new.completed_by_org_staff_id := null;
  elsif old.cskh_completed_date is null then
    new.completed_by_org_staff_id := private.resolve_lifecycle_org_staff_id(
      new.org_staff_updated_id,
      null,
      null
    );
  else
    new.completed_by_org_staff_id := old.completed_by_org_staff_id;
  end if;

  return new;
end
$function$

CREATE OR REPLACE FUNCTION private.preserve_aka_customer_during_lifecycle_projection()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_first_interest_at timestamptz := new.first_interest_at;
  v_last_interest_at timestamptz := new.last_interest_at;
  v_first_interest_staff_id bigint := new.first_interest_staff_id;
  v_last_interest_staff_id bigint := new.last_interest_staff_id;
  v_first_demo_at timestamptz := new.first_demo_at;
  v_last_demo_at timestamptz := new.last_demo_at;
  v_first_demo_staff_id bigint := new.first_demo_staff_id;
  v_last_demo_staff_id bigint := new.last_demo_staff_id;
  v_first_negotiation_at timestamptz := new.first_negotiation_at;
  v_last_negotiation_at timestamptz := new.last_negotiation_at;
  v_first_negotiation_staff_id bigint := new.first_negotiation_staff_id;
  v_last_negotiation_staff_id bigint := new.last_negotiation_staff_id;
  v_first_sale_at timestamptz := new.first_sale_at;
  v_last_sale_at timestamptz := new.last_sale_at;
  v_first_sale_staff_id bigint := new.first_sale_staff_id;
  v_last_sale_staff_id bigint := new.last_sale_staff_id;
  v_refresh_owner name;
begin
  if tg_op = 'INSERT' then
    -- Customer lifecycle fields are database-owned even when callers can set
    -- arbitrary custom GUCs. A normal insert always starts with null projection.
    new.first_interest_at := null;
    new.last_interest_at := null;
    new.first_interest_staff_id := null;
    new.last_interest_staff_id := null;
    new.first_demo_at := null;
    new.last_demo_at := null;
    new.first_demo_staff_id := null;
    new.last_demo_staff_id := null;
    new.first_negotiation_at := null;
    new.last_negotiation_at := null;
    new.first_negotiation_staff_id := null;
    new.last_negotiation_staff_id := null;
    new.first_sale_at := null;
    new.last_sale_at := null;
    new.first_sale_staff_id := null;
    new.last_sale_staff_id := null;
    return new;
  end if;

  if pg_catalog.current_setting(
       'app.aka_customer_lifecycle_projection',
       true
     ) = 'on' then
    select pg_catalog.pg_get_userbyid(function_row.proowner)
    into v_refresh_owner
    from pg_catalog.pg_proc as function_row
    where function_row.oid = pg_catalog.to_regprocedure(
      'private.refresh_aka_customer_lifecycle_projection(bigint)'
    );
  end if;

  if pg_catalog.current_setting(
       'app.aka_customer_lifecycle_projection',
       true
     ) is distinct from 'on'
     or current_user::name is distinct from v_refresh_owner then
    -- Outside the owner-executed projection path, silently retain all sixteen
    -- prior values. Setting the custom GUC alone cannot spoof attribution.
    new.first_interest_at := old.first_interest_at;
    new.last_interest_at := old.last_interest_at;
    new.first_interest_staff_id := old.first_interest_staff_id;
    new.last_interest_staff_id := old.last_interest_staff_id;
    new.first_demo_at := old.first_demo_at;
    new.last_demo_at := old.last_demo_at;
    new.first_demo_staff_id := old.first_demo_staff_id;
    new.last_demo_staff_id := old.last_demo_staff_id;
    new.first_negotiation_at := old.first_negotiation_at;
    new.last_negotiation_at := old.last_negotiation_at;
    new.first_negotiation_staff_id := old.first_negotiation_staff_id;
    new.last_negotiation_staff_id := old.last_negotiation_staff_id;
    new.first_sale_at := old.first_sale_at;
    new.last_sale_at := old.last_sale_at;
    new.first_sale_staff_id := old.first_sale_staff_id;
    new.last_sale_staff_id := old.last_sale_staff_id;
    return new;
  end if;

  -- This trigger sorts after every existing aka_customer BEFORE trigger. Reset
  -- technical updated_at, pipeline and staff-map side effects, then retain only
  -- the sixteen database-owned lifecycle projection values.
  new := old;
  new.first_interest_at := v_first_interest_at;
  new.last_interest_at := v_last_interest_at;
  new.first_interest_staff_id := v_first_interest_staff_id;
  new.last_interest_staff_id := v_last_interest_staff_id;
  new.first_demo_at := v_first_demo_at;
  new.last_demo_at := v_last_demo_at;
  new.first_demo_staff_id := v_first_demo_staff_id;
  new.last_demo_staff_id := v_last_demo_staff_id;
  new.first_negotiation_at := v_first_negotiation_at;
  new.last_negotiation_at := v_last_negotiation_at;
  new.first_negotiation_staff_id := v_first_negotiation_staff_id;
  new.last_negotiation_staff_id := v_last_negotiation_staff_id;
  new.first_sale_at := v_first_sale_at;
  new.last_sale_at := v_last_sale_at;
  new.first_sale_staff_id := v_first_sale_staff_id;
  new.last_sale_staff_id := v_last_sale_staff_id;
  return new;
end
$function$

CREATE OR REPLACE FUNCTION private.sync_aka_order_customer_lifecycle(p_order aka_order)
 RETURNS bigint[]
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_customer_ids bigint[];
  v_customer_id bigint;
  v_is_demo boolean;
  v_demo_at timestamptz;
  v_sale_at timestamptz;
  v_direct_staff_id bigint;
  v_sql_staff_id bigint;
  v_chat_staff_id uuid;
  v_org_staff_id bigint;
  v_staff_quality text;
  v_source_changed_at timestamptz;
begin
  if p_order.id is null then
    return '{}'::bigint[];
  end if;

  v_customer_ids := private.invalidate_aka_customer_lifecycle_source(
    'aka_order',
    p_order.id
  );

  -- org_product orders are read-only mirrors. Their authoritative evidence is
  -- captured from org_organization_product and its append-only history.
  if not coalesce(
    p_order.source_system = any (array['sql_account', 'legacy_manual']::text[]),
    false
  ) then
    return v_customer_ids;
  end if;

  v_customer_id := p_order.customer_id;
  if v_customer_id is null and p_order.organization_id is not null then
    select organization.customer_id
    into v_customer_id
    from public.org_organization as organization
    where organization.id = p_order.organization_id;
  end if;

  if v_customer_id is null or coalesce(p_order.is_deleted, false) then
    return v_customer_ids;
  end if;

  v_source_changed_at := coalesce(
    p_order.source_updated_at,
    p_order.updated_at,
    p_order.date_last_update,
    p_order.date_update_package,
    p_order.date_create,
    p_order.created_at,
    pg_catalog.statement_timestamp()
  );
  v_is_demo := coalesce(p_order.is_demo, false)
    or private.lifecycle_package_is_demo(
      p_order.package_type,
      p_order.package,
      false
    );

  if v_is_demo or p_order.trial_start_date is not null then
    v_demo_at := coalesce(
      p_order.trial_start_date,
      p_order.source_created_at,
      p_order.date_create,
      p_order.created_at
    );

    -- aka_order.org_staff_id is the owner/current manager, not the immutable
    -- SQL actor. Resolve the SQL creator, with chat staff only as fallback.
    v_direct_staff_id := null;
    v_sql_staff_id := p_order.staff_create_id_old;
    v_chat_staff_id := p_order.staff_id;

    v_org_staff_id := private.resolve_lifecycle_org_staff_id(
      v_direct_staff_id,
      v_sql_staff_id,
      v_chat_staff_id
    );
    v_staff_quality := private.lifecycle_staff_quality(
      v_org_staff_id,
      v_direct_staff_id,
      v_sql_staff_id,
      v_chat_staff_id
    );

    perform private.upsert_aka_customer_lifecycle_event(
      v_customer_id,
      'demo',
      v_demo_at,
      v_org_staff_id,
      'aka_order',
      p_order.id,
      'demo-current',
      case when p_order.trial_start_date is not null
        then 'exact' else 'inferred' end,
      v_staff_quality,
      50,
      v_source_changed_at
    );
  end if;

  if not v_is_demo and coalesce(p_order.is_paid, false) then
    v_sale_at := coalesce(
      p_order.purchase_date,
      p_order.date_update_package,
      p_order.date_create,
      p_order.source_created_at,
      p_order.created_at,
      p_order.source_updated_at
    );

    v_direct_staff_id := null;
    v_sql_staff_id := case
      when p_order.staff_update_id_old is not null
       and p_order.date_update_package is not null
       and p_order.date_update_package > coalesce(
         p_order.date_create,
         p_order.source_created_at,
         '-infinity'::timestamptz
       )
        then p_order.staff_update_id_old
      else coalesce(
        p_order.staff_create_id_old,
        p_order.staff_update_id_old
      )
    end;
    v_chat_staff_id := p_order.staff_id;

    v_org_staff_id := private.resolve_lifecycle_org_staff_id(
      v_direct_staff_id,
      v_sql_staff_id,
      v_chat_staff_id
    );
    v_staff_quality := private.lifecycle_staff_quality(
      v_org_staff_id,
      v_direct_staff_id,
      v_sql_staff_id,
      v_chat_staff_id
    );

    perform private.upsert_aka_customer_lifecycle_event(
      v_customer_id,
      'sale',
      v_sale_at,
      v_org_staff_id,
      'aka_order',
      p_order.id,
      'sale-current',
      case when p_order.purchase_date is not null
        or p_order.date_update_package is not null
        then 'exact' else 'inferred' end,
      v_staff_quality,
      50,
      v_source_changed_at
    );
  end if;

  return coalesce(v_customer_ids, '{}'::bigint[])
    || array[v_customer_id]::bigint[];
end
$function$

CREATE OR REPLACE FUNCTION private.sync_org_product_history_customer_lifecycle(p_history org_organization_product_history)
 RETURNS bigint[]
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_customer_ids bigint[];
  v_customer_id bigint;
  v_before_package_type text;
  v_before_package_name text;
  v_after_package_type text;
  v_after_package_name text;
  v_before_demo boolean;
  v_after_demo boolean;
  v_before_paid boolean;
  v_after_paid boolean;
  v_trial_before timestamptz;
  v_trial_after timestamptz;
  v_demo_first_after timestamptz;
  v_sale_first_before timestamptz;
  v_sale_first_after timestamptz;
  v_purchase_before timestamptz;
  v_purchase_after timestamptz;
  v_after_deleted boolean;
  v_org_staff_id bigint;
  v_staff_quality text;
  v_source_changed_at timestamptz;
begin
  if p_history.id is null then
    return '{}'::bigint[];
  end if;

  v_customer_ids := private.invalidate_aka_customer_lifecycle_source(
    'org_organization_product_history',
    p_history.id
  );

  select organization.customer_id
  into v_customer_id
  from public.org_organization as organization
  where organization.id = p_history.organization_id;

  if v_customer_id is null then
    return v_customer_ids;
  end if;

  v_org_staff_id := private.resolve_lifecycle_org_staff_id(
    p_history.actor_org_staff_id,
    null,
    null
  );
  v_staff_quality := private.lifecycle_staff_quality(
    v_org_staff_id,
    p_history.actor_org_staff_id,
    null,
    null
  );
  v_source_changed_at := coalesce(
    p_history.changed_at,
    p_history.archived_at,
    pg_catalog.statement_timestamp()
  );

  v_before_package_type := p_history.before_snapshot ->> 'package_type';
  v_before_package_name := p_history.before_snapshot ->> 'package_name';
  v_after_package_type := coalesce(
    p_history.after_snapshot ->> 'package_type',
    p_history.package_type
  );
  v_after_package_name := coalesce(
    p_history.after_snapshot ->> 'package_name',
    p_history.package_name
  );
  v_before_demo := private.lifecycle_package_is_demo(
    v_before_package_type,
    v_before_package_name,
    true
  );
  v_after_demo := private.lifecycle_package_is_demo(
    v_after_package_type,
    v_after_package_name,
    true
  );

  v_trial_before := nullif(
    p_history.before_snapshot ->> 'trial_start_date',
    ''
  )::timestamptz;
  v_trial_after := coalesce(
    nullif(p_history.after_snapshot ->> 'trial_start_date', '')::timestamptz,
    p_history.trial_start_date
  );
  v_demo_first_after := nullif(
    p_history.after_snapshot ->> 'demo_created_at',
    ''
  )::timestamptz;

  if p_history.operation in ('INSERT', 'UPDATE')
     and v_after_demo and (
    not v_before_demo
    or (
      v_trial_after is not null
      and v_trial_after is distinct from v_trial_before
    )
    or p_history.operation = 'INSERT'
    or v_demo_first_after is not null
       and nullif(
         p_history.before_snapshot ->> 'demo_created_at',
         ''
       )::timestamptz is distinct from v_demo_first_after
  ) then
    perform private.upsert_aka_customer_lifecycle_event(
      v_customer_id,
      'demo',
      coalesce(
        v_trial_after,
        v_demo_first_after,
        p_history.changed_at,
        p_history.archived_at
      ),
      v_org_staff_id,
      'org_organization_product_history',
      p_history.id,
      'demo',
      case when v_trial_after is not null
        or v_demo_first_after is not null
        then 'exact' else 'inferred' end,
      v_staff_quality,
      10,
      v_source_changed_at
    );
  end if;

  v_before_paid := coalesce(
    pg_catalog.lower(p_history.before_snapshot ->> 'is_paid') = 'true',
    false
  );
  v_after_paid := coalesce(
    pg_catalog.lower(p_history.after_snapshot ->> 'is_paid') = 'true',
    false
  );
  v_sale_first_before := nullif(
    p_history.before_snapshot ->> 'first_sale_at',
    ''
  )::timestamptz;
  v_sale_first_after := nullif(
    p_history.after_snapshot ->> 'first_sale_at',
    ''
  )::timestamptz;
  v_purchase_before := nullif(
    p_history.before_snapshot ->> 'purchase_date',
    ''
  )::timestamptz;
  v_purchase_after := coalesce(
    nullif(p_history.after_snapshot ->> 'purchase_date', '')::timestamptz,
    p_history.purchase_date
  );
  v_after_deleted := coalesce(
    pg_catalog.lower(p_history.after_snapshot ->> 'is_deleted') = 'true',
    false
  );

  if p_history.operation in ('INSERT', 'UPDATE')
     and not v_after_demo
     and v_after_paid
     and not v_after_deleted
     and (
       not v_before_paid
       or (
         v_sale_first_after is not null
         and v_sale_first_after is distinct from v_sale_first_before
       )
       or (
         v_purchase_after is not null
         and v_purchase_after is distinct from v_purchase_before
       )
       or p_history.operation = 'INSERT'
       or v_before_demo
     ) then
    perform private.upsert_aka_customer_lifecycle_event(
      v_customer_id,
      'sale',
      coalesce(
        v_purchase_after,
        v_sale_first_after,
        p_history.changed_at,
        p_history.archived_at
      ),
      v_org_staff_id,
      'org_organization_product_history',
      p_history.id,
      'sale',
      case when v_sale_first_after is not null
        or v_purchase_after is not null
        then 'exact' else 'inferred' end,
      v_staff_quality,
      10,
      v_source_changed_at
    );
  end if;

  return coalesce(v_customer_ids, '{}'::bigint[])
    || array[v_customer_id]::bigint[];
end
$function$

CREATE OR REPLACE FUNCTION private.trg_remap_customer_lifecycle_staff_links()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_sql_staff_ids bigint[];
  v_chat_staff_ids uuid[];
  v_customer_ids bigint[] := '{}'::bigint[];
  v_prior_customer_ids bigint[];
  v_order public.aka_order%rowtype;
  v_history public.aka_order_history%rowtype;
begin
  if tg_op = 'INSERT' then
    v_sql_staff_ids := array_remove(array[new.sql_staff_id]::bigint[], null);
    v_chat_staff_ids := array_remove(array[new.chat_staff_id]::uuid[], null);
  else
    if old.sql_staff_id is not distinct from new.sql_staff_id
       and old.chat_staff_id is not distinct from new.chat_staff_id then
      return new;
    end if;
    v_sql_staff_ids := array_remove(
      array[old.sql_staff_id, new.sql_staff_id]::bigint[],
      null
    );
    v_chat_staff_ids := array_remove(
      array[old.chat_staff_id, new.chat_staff_id]::uuid[],
      null
    );
  end if;

  for v_order in
    select order_row.*
    from public.aka_order as order_row
    where order_row.source_system in ('sql_account', 'legacy_manual')
      and (
        order_row.staff_create_id_old = any(v_sql_staff_ids)
        or order_row.staff_update_id_old = any(v_sql_staff_ids)
        or order_row.staff_id = any(v_chat_staff_ids)
      )
    order by order_row.id
  loop
    select coalesce(
      pg_catalog.array_agg(distinct event_row.customer_id),
      '{}'::bigint[]
    )
    into v_prior_customer_ids
    from public.aka_customer_lifecycle_event as event_row
    where event_row.source_table = 'aka_order'
      and event_row.source_row_id = v_order.id;

    v_customer_ids := v_customer_ids || v_prior_customer_ids;
    update public.aka_customer_lifecycle_event as event_row
    set invalidated_at = '-infinity'::timestamptz
    where event_row.source_table = 'aka_order'
      and event_row.source_row_id = v_order.id;

    v_customer_ids := v_customer_ids
      || private.sync_aka_order_customer_lifecycle(v_order);
  end loop;

  for v_history in
    select history.*
    from public.aka_order_history as history
    where history.source_system in ('sql_account', 'legacy_manual')
      and (
        history.actor_sql_staff_id = any(v_sql_staff_ids)
        or case
          when history.order_after_snapshot #>> '{order,staff_create_id_old}'
               ~ '^[1-9][0-9]*$'
            then (history.order_after_snapshot
                    #>> '{order,staff_create_id_old}')::bigint
        end = any(v_sql_staff_ids)
      )
    order by history.id
  loop
    select coalesce(
      pg_catalog.array_agg(distinct event_row.customer_id),
      '{}'::bigint[]
    )
    into v_prior_customer_ids
    from public.aka_customer_lifecycle_event as event_row
    where event_row.source_table = 'aka_order_history'
      and event_row.source_row_id = v_history.id;

    v_customer_ids := v_customer_ids || v_prior_customer_ids;
    update public.aka_customer_lifecycle_event as event_row
    set invalidated_at = '-infinity'::timestamptz
    where event_row.source_table = 'aka_order_history'
      and event_row.source_row_id = v_history.id;

    v_customer_ids := v_customer_ids
      || private.sync_aka_order_history_customer_lifecycle(v_history);
  end loop;

  perform private.refresh_aka_customer_lifecycle_projections(v_customer_ids);
  return new;
end
$function$

CREATE OR REPLACE FUNCTION private.trg_sync_aka_order_customer_lifecycle()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_customer_ids bigint[];
  v_history_customer_ids bigint[];
  v_target_customer_id bigint;
  v_history public.aka_order_history%rowtype;
begin
  if tg_op = 'DELETE' then
    v_customer_ids := private.invalidate_aka_customer_lifecycle_source(
      'aka_order',
      old.id
    );
    perform private.refresh_aka_customer_lifecycle_projections(v_customer_ids);
    return old;
  end if;

  v_customer_ids := private.sync_aka_order_customer_lifecycle(new);

  -- History is tied to the order identity. If the order is reassigned, move
  -- its already-recorded lifecycle evidence as one set instead of replaying
  -- every audit row and accidentally changing immutable actors.
  if tg_op = 'UPDATE'
     and (old.customer_id, old.organization_id)
         is distinct from (new.customer_id, new.organization_id) then
    v_target_customer_id := new.customer_id;
    if v_target_customer_id is null and new.organization_id is not null then
      select organization.customer_id
      into v_target_customer_id
      from public.org_organization as organization
      where organization.id = new.organization_id;
    end if;

    select coalesce(
      pg_catalog.array_agg(distinct event_row.customer_id),
      '{}'::bigint[]
    )
    into v_history_customer_ids
    from public.aka_customer_lifecycle_event as event_row
    where event_row.source_table = 'aka_order_history'
      and exists (
        select 1
        from public.aka_order_history as history
        where history.id = event_row.source_row_id
          and history.aka_order_id = new.id
      );

    for v_history in
      select history.*
      from public.aka_order_history as history
      where history.aka_order_id = new.id
      order by history.id
    loop
      v_customer_ids := coalesce(v_customer_ids, '{}'::bigint[])
        || private.sync_aka_order_history_customer_lifecycle(v_history);
    end loop;

    if v_target_customer_id is not null then
      v_customer_ids := coalesce(v_customer_ids, '{}'::bigint[])
        || array[v_target_customer_id]::bigint[];
    end if;

    v_customer_ids := coalesce(v_customer_ids, '{}'::bigint[])
      || coalesce(v_history_customer_ids, '{}'::bigint[]);
  end if;

  perform private.refresh_aka_customer_lifecycle_projections(v_customer_ids);
  return new;
end
$function$

CREATE OR REPLACE FUNCTION private.trg_sync_org_product_customer_lifecycle()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_customer_ids bigint[];
begin
  if tg_op = 'DELETE' then
    v_customer_ids := private.invalidate_aka_customer_lifecycle_source(
      'org_organization_product',
      old.id
    );
    perform private.refresh_aka_customer_lifecycle_projections(v_customer_ids);
    return old;
  end if;

  v_customer_ids := private.sync_org_product_customer_lifecycle(new);
  perform private.refresh_aka_customer_lifecycle_projections(v_customer_ids);
  return new;
end
$function$

CREATE OR REPLACE FUNCTION private.zalo_referral_backend_context_v1()
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
  v_role text := nullif(current_setting('request.jwt.claim.role', true), '');
  v_claims text := nullif(current_setting('request.jwt.claims', true), '');
begin
  if coalesce(current_setting('app.aka_customer_upsert_ctx', true), '') = '1' then
    return true;
  end if;
  if v_role is not null then
    return v_role = 'service_role';
  end if;
  if v_claims is not null then
    begin
      return coalesce((v_claims::jsonb ->> 'role') = 'service_role', false);
    exception when others then
      return false;
    end;
  end if;
  return session_user in ('postgres', 'supabase_admin', 'service_role');
end;
$function$

CREATE OR REPLACE FUNCTION private.zalo_referral_due_date_v1(p_now timestamp with time zone DEFAULT now())
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
  v_wall timestamp := p_now at time zone 'Asia/Ho_Chi_Minh';
  v_dow integer := extract(isodow from v_wall);
  v_minutes integer := extract(hour from v_wall)::integer * 60
                       + extract(minute from v_wall)::integer;
  v_date date := v_wall::date;
begin
  if v_dow = 7 then
    return ((v_date + 1) + time '08:30') at time zone 'Asia/Ho_Chi_Minh';
  end if;

  if v_dow = 6 then
    if v_minutes < 510 then
      return (v_date + time '08:30') at time zone 'Asia/Ho_Chi_Minh';
    elsif v_minutes < 1020 then
      return p_now;
    end if;
    return ((v_date + 2) + time '08:30') at time zone 'Asia/Ho_Chi_Minh';
  end if;

  if v_minutes < 510 then
    return (v_date + time '08:30') at time zone 'Asia/Ho_Chi_Minh';
  elsif v_minutes < 1080 then
    return p_now;
  end if;

  return ((v_date + 1) + time '08:30') at time zone 'Asia/Ho_Chi_Minh';
end;
$function$

CREATE OR REPLACE FUNCTION private.aka_agent_track_device_binding()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN
 IF OLD.aka_agent_device_identity_version=3 AND NEW.aka_agent_device_identity_version<>3 THEN RAISE EXCEPTION 'staff_client_device_locked'; END IF;
 IF (NEW.aka_agent_device_fingerprint_hash,NEW.aka_agent_device_identity_version) IS DISTINCT FROM (OLD.aka_agent_device_fingerprint_hash,OLD.aka_agent_device_identity_version) THEN
  NEW.aka_agent_device_binding_revision:=OLD.aka_agent_device_binding_revision+1;
 ELSE NEW.aka_agent_device_binding_revision:=OLD.aka_agent_device_binding_revision;
 END IF;
 RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION private.aka_agent_device_ambiguous(p_version smallint, p_hash text, p_staff_id bigint, p_prospective boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN
 IF p_hash IS NULL THEN RETURN false; END IF;
 IF EXISTS(SELECT 1 FROM private.aka_agent_device_collisions WHERE version=p_version AND fingerprint_hash=p_hash) THEN RETURN true; END IF;
 IF (p_prospective AND EXISTS(SELECT 1 FROM public.org_staff WHERE aka_agent_device_identity_version=p_version AND aka_agent_device_fingerprint_hash=p_hash AND id<>p_staff_id))
 OR (NOT p_prospective AND (SELECT count(*) FROM (SELECT 1 FROM public.org_staff WHERE aka_agent_device_identity_version=p_version AND aka_agent_device_fingerprint_hash=p_hash LIMIT 2) x)>1) THEN
  INSERT INTO private.aka_agent_device_collisions(version,fingerprint_hash) VALUES(p_version,p_hash) ON CONFLICT DO NOTHING;
  RETURN true;
 END IF;
 RETURN false;
END; $function$

CREATE OR REPLACE FUNCTION private.aka_agent_device_v3(p_staff_id bigint, p_action text, p_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
 s public.org_staff%ROWTYPE; receipt private.aka_agent_device_migrations%ROWTYPE;
 new_hash text:=p_data->>'fingerprintHash'; old_hash text:=p_data->>'legacyHash'; login_source text:=p_data->>'source';
 decision text:='allowed'; old_ambiguous boolean:=false; new_ambiguous boolean:=false;
 expected jsonb:=p_data->'expected'; request uuid; before_hash text; before_version smallint; before_revision bigint;
BEGIN
 IF jsonb_typeof(p_data->'fingerprintHash') IS DISTINCT FROM 'string' OR new_hash !~ '^[a-f0-9]{64}$'
 OR (p_data ? 'legacyHash' AND jsonb_typeof(p_data->'legacyHash') NOT IN ('null','string'))
 OR (old_hash IS NOT NULL AND old_hash !~ '^[a-f0-9]{64}$')
 OR login_source IS NULL OR login_source NOT IN ('manual','automatic','remembered','recovery') THEN RAISE EXCEPTION 'staff_client_invalid_input'; END IF;
 SELECT * INTO STRICT s FROM public.org_staff WHERE id=p_staff_id;
 before_hash:=s.aka_agent_device_fingerprint_hash; before_version:=s.aka_agent_device_identity_version; before_revision:=s.aka_agent_device_binding_revision;
 IF before_hash IS NOT NULL AND ((before_version=3 AND before_hash<>new_hash) OR (before_version=2 AND before_hash IS DISTINCT FROM old_hash)) THEN
  decision:='device_locked';
 ELSE
  old_ambiguous:=private.aka_agent_device_ambiguous(before_version,before_hash,s.id,false);
  new_ambiguous:=private.aka_agent_device_ambiguous(3::smallint,new_hash,s.id,true);
  IF login_source<>'manual' AND (before_hash IS NULL OR old_ambiguous OR new_ambiguous) THEN decision:='manual_login_required'; END IF;
 END IF;
 IF p_action='bind_device_v3' THEN
  IF jsonb_typeof(expected) IS DISTINCT FROM 'object' OR NOT (expected ?& ARRAY['hash','version','revision'])
   OR coalesce(expected->>'version','') NOT IN ('2','3') OR coalesce(expected->>'revision','') !~ '^[0-9]+$'
   OR (jsonb_typeof(expected->'hash') NOT IN ('null','string')) OR (expected->>'hash' IS NOT NULL AND expected->>'hash' !~ '^[a-f0-9]{64}$')
   OR coalesce(p_data->>'requestId','') !~ '^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$' THEN RAISE EXCEPTION 'staff_client_invalid_input'; END IF;
  request:=(p_data->>'requestId')::uuid;
  SELECT * INTO receipt FROM private.aka_agent_device_migrations WHERE request_id=request;
  IF FOUND THEN
   IF receipt.staff_id<>s.id OR receipt.organization_id<>s.organization_id OR receipt.source<>login_source OR receipt.new_hash<>new_hash
    OR receipt.old_hash IS DISTINCT FROM expected->>'hash' OR receipt.old_version::text IS DISTINCT FROM expected->>'version'
    OR receipt.old_revision::text IS DISTINCT FROM expected->>'revision' OR before_hash IS DISTINCT FROM receipt.new_hash
    OR before_version<>3 OR before_revision<>receipt.new_revision THEN decision:='device_locked'; END IF;
  ELSIF decision='allowed' THEN
   IF before_hash IS DISTINCT FROM expected->>'hash' OR before_version::text IS DISTINCT FROM expected->>'version'
    OR before_revision::text IS DISTINCT FROM expected->>'revision' THEN decision:='device_locked';
   ELSIF NOT s.is_policy_accepted THEN RAISE EXCEPTION 'staff_client_policy_required';
   ELSIF before_hash IS DISTINCT FROM new_hash OR before_version<>3 THEN
    UPDATE public.org_staff SET aka_agent_device_fingerprint_hash=new_hash,aka_agent_device_identity_version=3 WHERE id=s.id RETURNING * INTO s;
    INSERT INTO private.aka_agent_device_migrations(request_id,staff_id,organization_id,source,old_hash,old_version,old_revision,new_hash,new_revision)
     VALUES(request,s.id,s.organization_id,login_source,before_hash,before_version,before_revision,new_hash,s.aka_agent_device_binding_revision);
   END IF;
  END IF;
 END IF;
 RETURN jsonb_build_object('decision',decision,'automaticAllowed',NOT new_ambiguous,
  'needsBinding',s.aka_agent_device_identity_version<>3 OR s.aka_agent_device_fingerprint_hash IS DISTINCT FROM new_hash,
  'binding',jsonb_build_object('hash',s.aka_agent_device_fingerprint_hash,'version',s.aka_agent_device_identity_version,'revision',s.aka_agent_device_binding_revision::text));
END; $function$

CREATE OR REPLACE FUNCTION private.enforce_cskh_activity_near_expiry_cooldown()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_event_id uuid;
  v_effective_created_at timestamptz := coalesce(new.created_at, pg_catalog.statement_timestamp());
  v_candidate_customer_id bigint;
  v_candidate_event_reason text;
  v_candidate_current_reason text;
begin
  begin
    v_event_id := (new.gen_meta ->> 'event_id')::uuid;
  exception
    when others then
      raise exception using errcode = '22023', message = 'cskh_activity_event_id_invalid';
  end;

  select candidate.customer_id, candidate.event_reason, candidate.reason
  into v_candidate_customer_id, v_candidate_event_reason, v_candidate_current_reason
  from public.find_cskh_activity_crm_candidate(v_event_id) candidate
  limit 1;

  if v_candidate_customer_id is null
     or v_candidate_customer_id is distinct from new.customer_id
     or (
       new.crm_type_id = 23
       and v_candidate_current_reason not in ('monthly_expiring_15d', 'yearly_expiring_30d')
     )
     or (
       new.crm_type_id = 15
       and v_candidate_event_reason not in ('monthly_expiring_15d', 'yearly_expiring_30d')
     ) then
    raise exception using errcode = 'P0001', message = 'cskh_activity_candidate_no_longer_eligible';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      pg_catalog.format('cskh_activity_near_expiry_72h:%s', new.customer_id),
      0
    )
  );

  if exists (
    select 1
    from public.aka_crm existing
    where existing.customer_id = new.customer_id
      and existing.crm_type_id in (15, 23)
      and existing.source_type = 'cskh_activity_near_expiry'
      and existing.created_at > v_effective_created_at - interval '72 hours'
      and existing.created_at <= v_effective_created_at
  ) then
    raise exception using errcode = 'P0001', message = 'cskh_activity_near_expiry_cooldown_72h';
  end if;

  return new;
end;
$function$

