CREATE OR REPLACE FUNCTION private.validate_auto_content_template_secondary_groups()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  previous_secondary_group_ids bigint[] := '{}'::bigint[];
begin
  if tg_op = 'UPDATE' then
    previous_secondary_group_ids := coalesce(old.secondary_group_ids, '{}'::bigint[]);
  end if;

  if exists (
    select 1
    from unnest(new.secondary_group_ids) as membership(group_id)
    left join public.auto_content_groups as content_group
      on content_group.id = membership.group_id
    where content_group.id is null
       or content_group.is_delete is not false
       or content_group.organization_id is distinct from new.organization_id
  ) then
    raise exception 'secondary_group_ids must reference non-deleted groups in the same organization'
      using errcode = '23503';
  end if;

  if exists (
    select 1
    from unnest(new.secondary_group_ids) as membership(group_id)
    join public.auto_content_groups as content_group
      on content_group.id = membership.group_id
    where not (membership.group_id = any (previous_secondary_group_ids))
      and content_group.is_active is not true
  ) then
    raise exception 'new secondary_group_ids must reference active groups'
      using errcode = '23514';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.aka_order_history_has_forbidden_keys(p_value jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare
  v_key text;
  v_normalized_key text;
  v_child jsonb;
begin
  if p_value is null then
    return false;
  end if;

  if pg_catalog.jsonb_typeof(p_value) = 'object' then
    for v_key, v_child in
      select entry.key, entry.value
      from pg_catalog.jsonb_each(p_value) as entry
    loop
      v_normalized_key := pg_catalog.regexp_replace(
        lower(v_key),
        '[^a-z0-9]',
        '',
        'g'
      );
      if v_normalized_key = any(array[
           'username', 'password', 'passwd', 'secret', 'token',
           'accesstoken', 'refreshtoken', 'apikey', 'authorization',
           'cookie', 'credential', 'credentials', 'deviceinfo',
           'computerinfo', 'connectionstring', 'config', 'configuration',
           'raw', 'rawsnapshot', 'sourcesnapshot'
         ]::text[])
         or private.aka_order_history_has_forbidden_keys(v_child) then
        return true;
      end if;
    end loop;
  elsif pg_catalog.jsonb_typeof(p_value) = 'array' then
    for v_child in
      select item.value
      from pg_catalog.jsonb_array_elements(p_value) as item
    loop
      if private.aka_order_history_has_forbidden_keys(v_child) then
        return true;
      end if;
    end loop;
  end if;

  return false;
end;
$function$

CREATE OR REPLACE FUNCTION private.facebook_random_unit_gate(p_campaign bigint, p_account bigint, p_claim uuid, p_count integer)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE t jsonb; enabled boolean;
BEGIN
 SELECT a.facebook_random_run_enabled INTO enabled FROM public.auto_accounts a WHERE a.id=p_account AND a.flatform_type='facebook';
 IF NOT FOUND THEN RETURN NULL; END IF;
 SELECT x INTO t FROM public.auto_account_random_run_days d, jsonb_array_elements(d.state->'turns') x
 WHERE d.account_id=p_account AND d.status='open' AND x->>'claimToken'=p_claim::text AND (x->>'campaignId')::bigint=p_campaign AND x->>'status'='running';
 IF enabled AND t IS NULL OR NOT enabled AND t IS NOT NULL THEN RETURN 'random_mode_changed'; END IF;
 IF t IS NULL THEN RETURN NULL; END IF;
 IF (t->>'unit'='data' AND (t->>'processed')::int+p_count>(t->>'quantity')::int)
   OR (t->>'unit'<>'data' AND (t->>'processed')::int>=1) THEN RETURN 'random_budget_exhausted'; END IF;
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION private.protect_org_lifecycle_attribution()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_product_actor bigint;
  v_product_at timestamptz;
begin
  if tg_op = 'INSERT' then
    new.demo_created_by := null;
    new.first_sale_by := null;
    new.demo_created_at := null;
    new.first_sale_at := null;
    return new;
  end if;

  if old.demo_created_at is not null then
    new.demo_created_at := old.demo_created_at;
    new.demo_created_by := old.demo_created_by;
  elsif new.demo_created_at is not null then
    select product.demo_created_by, product.demo_created_at
    into v_product_actor, v_product_at
    from public.org_organization_product as product
    where product.organization_id = new.id
      and product.demo_created_at is not null
    order by product.demo_created_at, product.id
    limit 1;

    if not found
       or new.demo_created_at is distinct from v_product_at
       or new.demo_created_by is distinct from v_product_actor
       or (
         old.demo_created_by is not null
         and v_product_actor is distinct from old.demo_created_by
       ) then
      new.demo_created_at := old.demo_created_at;
      new.demo_created_by := old.demo_created_by;
    else
      new.demo_created_at := v_product_at;
      new.demo_created_by := v_product_actor;
    end if;
  else
    new.demo_created_at := old.demo_created_at;
    new.demo_created_by := old.demo_created_by;
  end if;

  if old.first_sale_at is not null then
    new.first_sale_at := old.first_sale_at;
    new.first_sale_by := old.first_sale_by;
  elsif new.first_sale_at is not null then
    select product.first_sale_by, product.first_sale_at
    into v_product_actor, v_product_at
    from public.org_organization_product as product
    where product.organization_id = new.id
      and product.first_sale_at is not null
    order by product.first_sale_at, product.id
    limit 1;

    if not found
       or new.first_sale_at is distinct from v_product_at
       or new.first_sale_by is distinct from v_product_actor
       or (
         old.first_sale_by is not null
         and v_product_actor is distinct from old.first_sale_by
       ) then
      new.first_sale_at := old.first_sale_at;
      new.first_sale_by := old.first_sale_by;
    else
      new.first_sale_at := v_product_at;
      new.first_sale_by := v_product_actor;
    end if;
  else
    new.first_sale_at := old.first_sale_at;
    new.first_sale_by := old.first_sale_by;
  end if;

  return new;
end
$function$

CREATE OR REPLACE FUNCTION private.trg_touch_aka_salesopportunity()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  new.updated_at := pg_catalog.statement_timestamp();

  if tg_op = 'INSERT' then
    new.created_at := coalesce(new.created_at, pg_catalog.statement_timestamp());
    new.stage_entered_at := coalesce(
      new.stage_entered_at,
      pg_catalog.statement_timestamp()
    );
    new.version := coalesce(nullif(new.version, 0), 1);
  else
    new.version := old.version + 1;
    if new.stage is distinct from old.stage then
      new.stage_entered_at := pg_catalog.statement_timestamp();
    end if;
  end if;

  if new.status = 'open' then
    new.closed_at := null;
    if tg_op = 'UPDATE' and old.status <> 'open' then
      new.probability := case new.stage
        when 'qualification' then 10
        when 'interested' then 30
        when 'trial' then 55
        when 'quote_negotiation' then 75
        else new.probability
      end;
      new.reopen_at := pg_catalog.clock_timestamp();
    end if;
  elsif new.status = 'won' then
    new.probability := 100;
    if tg_op = 'INSERT'
       or old.status is distinct from new.status
       or new.closed_at is null
    then
      new.closed_at := pg_catalog.clock_timestamp();
    end if;
  else
    new.probability := 0;
    if tg_op = 'INSERT'
       or old.status is distinct from new.status
       or new.closed_at is null
    then
      new.closed_at := pg_catalog.clock_timestamp();
    end if;
  end if;

  return new;
end
$function$

CREATE OR REPLACE FUNCTION private.enforce_birthday_crm23_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_job_id uuid;
  v_gom_id uuid;
  v_birthday_date date;
  v_days_left integer;
  v_entitlement_source text;
  v_entitlement_id bigint;
  v_job private.birthday_offer_jobs%rowtype;
  v_identity jsonb;
  v_lifecycle jsonb;
  v_selected jsonb;
  v_expected_note text;
  v_auto_send_enabled boolean := false;
  v_schema_version integer;
  v_rules_version text;
  v_meta_lifecycle text;
  v_meta_is_paid boolean;
  v_meta_is_demo boolean;
  v_meta_product_id bigint;
  v_meta_product_code text;
  v_meta_product_name text;
  v_meta_package_name text;
  v_meta_expires_on date;
  v_meta_greeting_raw_message_id uuid;
  v_greeting_echo jsonb;
begin
  if new.crm_type_id is distinct from 23 then
    raise exception using errcode = '22023', message = 'birthday_crm_type_must_be_23';
  end if;

  if coalesce(new.source_type, '') !~ '^birthday_near_expiry:[0-9]{4}-[0-9]{2}-[0-9]{2}$' then
    raise exception using errcode = '22023', message = 'birthday_crm_source_type_invalid';
  end if;

  begin
    v_job_id := (new.gen_meta #>> '{birthday_offer_v1,job_id}')::uuid;
    v_gom_id := (new.gen_meta #>> '{birthday_offer_v1,birthday_gom_id}')::uuid;
    v_birthday_date := (new.gen_meta #>> '{birthday_offer_v1,birthday_date_vn}')::date;
    v_days_left := (new.gen_meta #>> '{birthday_offer_v1,days_left}')::integer;
    v_entitlement_source := new.gen_meta #>> '{birthday_offer_v1,entitlement_source}';
    v_entitlement_id := (new.gen_meta #>> '{birthday_offer_v1,entitlement_id}')::bigint;
    v_schema_version := (new.gen_meta ->> 'schema_version')::integer;
    v_rules_version := new.gen_meta ->> 'rules_version';
    v_meta_lifecycle := new.gen_meta ->> 'lifecycle';
    v_meta_is_paid := (new.gen_meta ->> 'is_paid')::boolean;
    v_meta_is_demo := (new.gen_meta ->> 'is_demo')::boolean;
    v_meta_product_id := nullif(new.gen_meta ->> 'product_id', '')::bigint;
    v_meta_product_code := new.gen_meta ->> 'product_code';
    v_meta_product_name := new.gen_meta ->> 'product_name';
    v_meta_package_name := new.gen_meta ->> 'package_name';
    v_meta_expires_on := (new.gen_meta ->> 'expires_on')::date;
    v_meta_greeting_raw_message_id := (new.gen_meta ->> 'greeting_raw_message_id')::uuid;
  exception
    when others then
      raise exception using errcode = '22023', message = 'birthday_crm_gen_meta_invalid';
  end;

  if v_job_id is null or v_gom_id is null or v_birthday_date is null
     or v_days_left is null or v_entitlement_source is null or v_entitlement_id is null then
    raise exception using errcode = '22023', message = 'birthday_crm_gen_meta_missing';
  end if;

  if not (
    coalesce(new.gen_meta ? 'schema_version', false)
    and coalesce(new.gen_meta ? 'rules_version', false)
    and coalesce(new.gen_meta ? 'lifecycle', false)
    and coalesce(new.gen_meta ? 'is_paid', false)
    and coalesce(new.gen_meta ? 'is_demo', false)
    and coalesce(new.gen_meta ? 'product_id', false)
    and coalesce(new.gen_meta ? 'product_code', false)
    and coalesce(new.gen_meta ? 'product_name', false)
    and coalesce(new.gen_meta ? 'package_name', false)
    and coalesce(new.gen_meta ? 'expires_on', false)
    and coalesce(new.gen_meta ? 'greeting_raw_message_id', false)
  ) then
    raise exception using errcode = '22023', message = 'birthday_crm_provenance_missing';
  end if;

  if v_schema_version is distinct from 1
     or v_rules_version is distinct from 'birthday_offer_v1_20260827'
     or v_meta_lifecycle is distinct from 'active_near_expiry' then
    raise exception using errcode = '22023', message = 'birthday_crm_provenance_version_mismatch';
  end if;

  v_expected_note := pg_catalog.format(
    'Khách hàng sinh nhật - chỉ còn %s ngày hết hạn - tạo ưu đãi giảm 10%% + tặng ngay nếu gia hạn trong hôm nay',
    v_days_left
  );

  if new.source_type <> 'birthday_near_expiry:' || v_birthday_date::text then
    raise exception using errcode = '22023', message = 'birthday_crm_source_date_mismatch';
  end if;

  if v_birthday_date is distinct from
       (pg_catalog.now() at time zone 'Asia/Ho_Chi_Minh')::date then
    raise exception using errcode = 'P0001', message = 'birthday_crm_birthday_day_expired';
  end if;

  begin
    select coalesce(
      (u.request_options #>> '{workflow,auto_send_enabled}')::boolean,
      false
    ) into v_auto_send_enabled
    from public.ai_using u
    where u.code = 'birthday_offer_analyze_v1'
      and u.is_active
    order by u.updated_at desc nulls last, u.id desc
    limit 1;
  exception
    when others then
      v_auto_send_enabled := false;
  end;

  if not coalesce(v_auto_send_enabled, false) then
    raise exception using errcode = 'P0001', message = 'birthday_crm_workflow_disabled';
  end if;

  if coalesce(new.note, '') <> v_expected_note then
    raise exception using errcode = '22023', message = 'birthday_crm_note_contract_mismatch';
  end if;

  if new.suggested_channel_id is distinct from 8 then
    raise exception using errcode = '22023', message = 'birthday_crm_channel_mismatch';
  end if;

  if coalesce(new.suggested_content, '') <> v_expected_note then
    raise exception using errcode = '22023', message = 'birthday_crm_suggested_content_mismatch';
  end if;

  if new.gen_agent is distinct from 'birthday-offer-v1' then
    raise exception using errcode = '22023', message = 'birthday_crm_gen_agent_mismatch';
  end if;

  if new.source_order_id is not null then
    raise exception using errcode = '22023', message = 'birthday_crm_source_order_id_must_be_null';
  end if;

  select j.* into v_job
  from private.birthday_offer_jobs j
  where j.id = v_job_id
    and j.birthday_gom_id = v_gom_id
    and j.birthday_date_vn = v_birthday_date
  for update;

  if not found then
    raise exception using errcode = 'P0001', message = 'birthday_crm_job_not_found';
  end if;

  if v_job.status <> 'processing' or v_job.stage <> 'crm23'
     or v_job.lease_expires_at <= pg_catalog.now() then
    raise exception using errcode = 'P0001', message = 'birthday_crm_job_not_claimed';
  end if;

  if new.customer_id is null or new.customer_id is distinct from v_job.customer_id then
    raise exception using errcode = 'P0001', message = 'birthday_crm_customer_mismatch';
  end if;

  v_identity := private.resolve_birthday_customer_v1(v_gom_id);
  if v_identity ->> 'status' <> 'resolved'
     or (v_identity ->> 'customer_id')::bigint is distinct from new.customer_id then
    raise exception using errcode = 'P0001', message = 'birthday_crm_identity_changed';
  end if;

  v_lifecycle := private.classify_birthday_customer_v1(new.customer_id, v_birthday_date);
  v_selected := v_lifecycle -> 'selected_entitlement';

  if v_lifecycle ->> 'status' <> 'active_near_expiry'
     or (v_lifecycle ->> 'days_left')::integer not between 0 and 15 then
    raise exception using errcode = 'P0001', message = 'birthday_crm_no_longer_near_expiry';
  end if;

  if v_days_left is distinct from (v_selected ->> 'days_left')::integer
     or v_entitlement_source is distinct from v_selected ->> 'source'
     or v_entitlement_id is distinct from (v_selected ->> 'id')::bigint
     or new.source_expiration_date is distinct from (v_selected ->> 'expires_on')::date
     or new.source_expiration_source is distinct from v_selected ->> 'source'
     or v_meta_expires_on is distinct from (v_selected ->> 'expires_on')::date
     or v_meta_is_paid is distinct from (v_selected ->> 'is_paid')::boolean
     or v_meta_is_demo is distinct from (v_selected ->> 'is_demo')::boolean
     or v_meta_product_id is distinct from nullif(v_selected ->> 'product_id', '')::bigint
     or v_meta_product_code is distinct from v_selected ->> 'product_code'
     or v_meta_product_name is distinct from v_selected ->> 'product_name'
     or v_meta_package_name is distinct from v_selected ->> 'package_name' then
    raise exception using errcode = 'P0001', message = 'birthday_crm_entitlement_snapshot_mismatch';
  end if;

  v_greeting_echo := private.birthday_greeting_echo_v1(v_gom_id);
  if not coalesce((v_greeting_echo ->> 'confirmed')::boolean, false)
     or v_meta_greeting_raw_message_id is distinct from
       (v_greeting_echo ->> 'message_id')::uuid then
    raise exception using errcode = 'P0001', message = 'birthday_crm_greeting_echo_mismatch';
  end if;

  if new.pancake_url is distinct from v_job.delivery_snapshot ->> 'pancake_url' then
    raise exception using errcode = 'P0001', message = 'birthday_crm_delivery_mismatch';
  end if;

  if v_entitlement_source = 'org_organization_product'
     and new.org_organization_product_id is distinct from v_entitlement_id then
    raise exception using errcode = 'P0001', message = 'birthday_crm_org_product_mismatch';
  end if;

  if v_entitlement_source = 'aka_order'
     and new.org_organization_product_id is not null then
    raise exception using errcode = 'P0001', message = 'birthday_crm_unexpected_org_product';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      pg_catalog.format('birthday_crm23:%s:%s', new.customer_id, v_birthday_date),
      0
    )
  );

  if exists (
    select 1 from public.aka_crm existing
    where existing.customer_id = new.customer_id
      and existing.source_type = new.source_type
  ) then
    raise exception using errcode = '23505', message = 'birthday_crm_customer_day_duplicate';
  end if;

  if exists (
    select 1 from public.aka_crm existing
    where existing.gen_meta #>> '{birthday_offer_v1,job_id}' = v_job_id::text
  ) then
    raise exception using errcode = '23505', message = 'birthday_crm_job_duplicate';
  end if;

  new.gen_agent := 'birthday-offer-v1';
  new.gen_status := coalesce(new.gen_status, 'scheduled');
  new.gen_at := coalesce(new.gen_at, pg_catalog.now());
  return new;
end;
$function$

