CREATE OR REPLACE FUNCTION private.trg_loyalty_from_aka_order_history()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_old_customer_id bigint;
  v_new_customer_id bigint;
  v_customer_text text;
  v_product_code text;
  v_event_key text;
begin
  -- org_product rows are projections of org_organization_product. Processing
  -- them here would count the same commercial change a second time.
  if new.source_system <> 'sql_account'
     or new.outcome <> 'committed'
     or new.event_origin in ('reconcile', 'migration_baseline') then
    return new;
  end if;

  v_customer_text := new.order_before_snapshot ->> 'customer_id';
  if v_customer_text ~ '^[0-9]+$' then
    v_old_customer_id := v_customer_text::bigint;
  end if;

  v_customer_text := new.order_after_snapshot ->> 'customer_id';
  if v_customer_text ~ '^[0-9]+$' then
    v_new_customer_id := v_customer_text::bigint;
  end if;

  if v_new_customer_id is null and new.aka_order_id is not null then
    select order_row.customer_id
    into v_new_customer_id
    from public.aka_order as order_row
    where order_row.id = new.aka_order_id;
  end if;

  perform private.reconcile_sql_account_loyalty(v_old_customer_id);
  if v_new_customer_id is distinct from v_old_customer_id then
    perform private.reconcile_sql_account_loyalty(v_new_customer_id);
  end if;

  if v_new_customer_id is not null
     and new.purchase_mode_after = 'renewal'
     and new.purchase_date_after is not null
     and new.purchase_date_after is distinct from new.purchase_date_before then
    v_event_key := 'sql_renewal:' || new.source_record_id::text || ':'
      || extract(epoch from new.purchase_date_after)::text;

    perform private.upsert_customer_loyalty_event(
      v_new_customer_id,
      'renewal',
      new.purchase_date_after,
      'exact',
      'sql_account',
      'aka_order_history',
      new.id::text,
      v_event_key,
      pg_catalog.jsonb_build_object(
        'aka_order_history_id', new.id,
        'aka_order_id', new.aka_order_id,
        'source_record_id', new.source_record_id,
        'purchase_date_before', new.purchase_date_before,
        'purchase_date_after', new.purchase_date_after,
        'changed_fields', new.changed_fields
      )
    );
  end if;

  if v_new_customer_id is not null
     and new.product_name_after is distinct from new.product_name_before then
    for v_product_code in
      select after_code.product_code
      from private.aka_loyalty_sql_product_codes(
        new.product_name_after
      ) as after_code
      where not exists (
        select 1
        from private.aka_loyalty_sql_product_codes(
          new.product_name_before
        ) as before_code
        where before_code.product_code = after_code.product_code
      )
    loop
      v_event_key := 'sql_product:' || v_new_customer_id::text
        || ':' || v_product_code;

      update public.aka_customer_loyalty_event as event
      set
        occurred_at = coalesce(
          new.source_effective_at,
          new.changed_at
        ),
        date_quality = 'exact',
        source_table = 'aka_order_history',
        source_record_id = new.id::text,
        source_payload = pg_catalog.jsonb_build_object(
          'aka_order_history_id', new.id,
          'aka_order_id', new.aka_order_id,
          'source_record_id', new.source_record_id,
          'product_code', v_product_code,
          'product_list_before', new.product_name_before,
          'product_list_after', new.product_name_after
        ),
        updated_at = pg_catalog.statement_timestamp()
      where event.source_event_key = v_event_key
        and event.invalidated_at is null;
    end loop;

    perform private.refresh_customer_loyalty_snapshot(v_new_customer_id);
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.facebook_random_unit_recover(p_campaign bigint, p_account bigint, p_unit uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE c record;t jsonb;
BEGIN
 SELECT runtime_unit_input_data_ids ids,runtime_claim_token claim INTO c FROM public.auto_campaigns WHERE id=p_campaign AND account_id=p_account AND runtime_unit_token=p_unit;
 IF NOT FOUND THEN RETURN; END IF;
 SELECT x INTO t FROM public.auto_account_random_run_days d,jsonb_array_elements(d.state->'turns') x
 WHERE d.account_id=p_account AND d.status='open' AND x->>'unitToken'=p_unit::text AND x->>'status'='running';
 IF t IS NULL THEN RETURN; END IF;
 PERFORM private.facebook_random_unit_settled(p_campaign,p_account,p_unit,true);
 UPDATE public.auto_campaign_input_data SET status='hoàn thành',note='Lượt ngẫu nhiên bị gián đoạn; kết quả chưa rõ, không tự thực hiện lại'
 WHERE campaign_id=p_campaign AND id=ANY(c.ids) AND status IN ('đang chạy','chờ xử lý');
 IF t->>'unit'<>'data' THEN
   UPDATE public.auto_campaigns SET status='tạm dừng',note='Lượt ngẫu nhiên bị gián đoạn; kiểm tra kết quả trước khi chạy lại' WHERE id=p_campaign;
 END IF;
 PERFORM private.facebook_random_finalize_turn(p_campaign,p_account,c.claim,p_unit,true);
END $function$

