CREATE OR REPLACE FUNCTION private.trg_lock_org_product_aka_order_sync()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_first_organization_id bigint;
  v_second_organization_id bigint;
begin
  if tg_op = 'INSERT' then
    v_first_organization_id := new.organization_id;
  elsif tg_op = 'DELETE' then
    v_first_organization_id := old.organization_id;
  else
    v_first_organization_id := least(old.organization_id, new.organization_id);
    v_second_organization_id := greatest(old.organization_id, new.organization_id);
    if v_second_organization_id = v_first_organization_id then
      v_second_organization_id := null;
    end if;
  end if;

  if v_first_organization_id is not null then
    perform pg_catalog.pg_advisory_xact_lock(
      private.aka_order_organization_lock_key(v_first_organization_id)
    );
  end if;
  if v_second_organization_id is not null then
    perform pg_catalog.pg_advisory_xact_lock(
      private.aka_order_organization_lock_key(v_second_organization_id)
    );
  end if;

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.reconcile_one_aka_order_non_org_status(p_order_id bigint)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_order public.aka_order%rowtype;
  v_package_type text;
  v_is_demo boolean;
  v_is_paid boolean;
  v_status text;
  v_updated integer;
begin
  select *
  into v_order
  from public.aka_order
  where id = p_order_id
    and source_system in ('sql_account', 'legacy_manual')
  for update;

  if not found then
    return false;
  end if;

  v_package_type := private.aka_order_non_org_package_type(
    v_order.package_type,
    v_order.package
  );
  v_is_demo := private.aka_order_non_org_is_demo(
    v_order.source_snapshot,
    v_package_type
  );
  v_is_paid := private.aka_order_non_org_is_paid(
    v_order.source_snapshot,
    v_package_type,
    v_order.thanh_tien::numeric
  );
  v_status := private.aka_order_non_org_status(
    v_order.source_snapshot,
    v_order.is_deleted,
    v_order.is_lock,
    v_order.date_expiration,
    v_is_paid,
    v_is_demo,
    statement_timestamp()
  );

  update public.aka_order
  set
    package_type = v_package_type,
    is_demo = v_is_demo,
    is_paid = v_is_paid,
    order_status = v_status,
    is_active = v_status in (
      'demo_active',
      'paid_active',
      'unpaid_active'
    ),
    sync_version = sync_version + 1
  where id = v_order.id
    and (
      package_type,
      is_demo,
      is_paid,
      order_status,
      is_active
    ) is distinct from (
      v_package_type,
      v_is_demo,
      v_is_paid,
      v_status,
      v_status in ('demo_active', 'paid_active', 'unpaid_active')
    );

  get diagnostics v_updated = row_count;
  return v_updated = 1;
end;
$function$

CREATE OR REPLACE FUNCTION private.trg_sync_org_product_to_aka_order()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if tg_op = 'DELETE' then
    perform pg_catalog.pg_advisory_xact_lock(
      private.aka_order_organization_lock_key(old.organization_id)
    );
    -- The FK cascade deletes aka_order after this BEFORE trigger. The generic
    -- aka_order DELETE audit trigger records the immutable source-delete event.
    return old;
  end if;

  perform private.sync_org_product_to_aka_order(
    new.id,
    case when tg_op = 'INSERT' then 'insert' else 'update' end
  );
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.guard_crm_trial_care_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare d jsonb; existing record; existing_decision jsonb; new_source jsonb; prior_source jsonb;
begin
 if new.cskh_completed_date is not null or not private.crm_trial_care_candidate_v1(to_jsonb(new)) then return new; end if;
 if new.customer_id is not null then perform pg_advisory_xact_lock(hashtextextended('crm_trial_care:'||new.customer_id,0)); end if;
 d:=public.crm_trial_care_decision_v1(to_jsonb(new));
 new.gen_meta:=private.crm_trial_care_metadata_v1(new.gen_meta,d);
 new_source:=d->'source';
 if new_source is not null and new_source<>'null'::jsonb
  and (d->>'status' in ('eligible','purchased') or d->>'reason'='partially_purchased_products') then
  for existing in select c.* from public.aka_crm c where c.customer_id=new.customer_id
   and c.id is distinct from new.id and c.crm_type_id is not distinct from new.crm_type_id
   and c.cskh_due_date is not distinct from new.cskh_due_date and c.note is not distinct from new.note
  loop
   existing_decision:=public.crm_trial_care_decision_v1(to_jsonb(existing)-'cskh_completed_date');
   prior_source:=existing_decision->'source';
   if (existing_decision->>'status' in ('eligible','purchased') or existing_decision->>'reason'='partially_purchased_products')
    and prior_source->>'source_type'=new_source->>'source_type' and prior_source->>'source_id'=new_source->>'source_id'
    and prior_source->>'kind'=new_source->>'kind' and (prior_source->'product_ids') @> (new_source->'product_ids')
    and (new_source->'product_ids') @> (prior_source->'product_ids')
    and ((prior_source->>'started_at')::timestamptz at time zone 'Asia/Ho_Chi_Minh')::date=
      ((new_source->>'started_at')::timestamptz at time zone 'Asia/Ho_Chi_Minh')::date then
    raise exception 'crm_trial_care_source_schedule_unique' using errcode='23505',constraint='crm_trial_care_source_schedule_unique';
   end if;
  end loop;
 end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION private.enqueue_crm_trial_care_change_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare customer bigint; item record;
begin
 if tg_table_name='aka_crm' then
  if tg_op='UPDATE' and old.purchase_date is not null and old.cskh_completed_date is not null then
   -- Re-evaluate the previous owner after a correction, clear, or relink, too.
   perform public.crm_enqueue_trial_care_v1(old.customer_id,'purchase_crm_corrected');
  end if;
  if tg_op='INSERT' and new.cskh_completed_date is null and private.crm_trial_care_candidate_v1(to_jsonb(new)) then
   -- Close the purchase/create commit-order race: every newly inserted schedule
   -- enqueues after its own insertion, even if a purchase queue ran first.
   perform public.crm_enqueue_trial_care_v1(new.customer_id,'trial_schedule_created');
  end if;
  if new.purchase_date is not null and new.cskh_completed_date is not null then
   perform public.crm_enqueue_trial_care_v1(new.customer_id,'completed_purchase_crm');
  end if;
 elsif tg_table_name='org_organization_product' then
  if new.is_paid then
   select customer_id into customer from public.org_organization where id=new.organization_id;
   perform public.crm_enqueue_trial_care_v1(customer,'paid_entitlement');
  end if;
 elsif tg_table_name='aka_order' then
  if new.source_system='sql_account' and new.is_paid then
   perform public.crm_enqueue_trial_care_v1(new.customer_id,'paid_sql_entitlement');
  end if;
 elsif tg_table_name='aka_sale_order' then
  if new.status in ('paid','upgrading','completed','upgrade_failed') and new.paid_at is not null then
   for item in select distinct coalesce(i.customer_id,new.customer_id) as customer_id from public.aka_sale_order_item i where i.sale_order_id=new.id
    union select new.customer_id loop perform public.crm_enqueue_trial_care_v1(item.customer_id,'paid_sale_order'); end loop;
  end if;
 elsif tg_table_name='aka_sale_order_item' then
  select coalesce(new.customer_id,o.customer_id) into customer from public.aka_sale_order o where o.id=new.sale_order_id and o.status in ('paid','upgrading','completed','upgrade_failed') and o.paid_at is not null;
  perform public.crm_enqueue_trial_care_v1(customer,'paid_sale_order_item');
 end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION private.crm_trial_care_metadata_v1(p_meta jsonb, p_decision jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare m jsonb:=coalesce(p_meta,'{}'); marker jsonb;
begin
 if jsonb_typeof(m)<>'object' then m:=jsonb_build_object('trial_care_original_meta',m); end if;
 if p_decision->>'status' in ('purchased','needs_review') then
  marker:=jsonb_build_object('version',1,'status',case when p_decision->>'status'='purchased' then 'suppressed' else 'needs_review' end,
    'reason',p_decision->>'reason','evidence',p_decision->'evidence','source',p_decision->'source');
  if (m->'trial_care')-'evaluated_at' is distinct from marker then
   m:=jsonb_set(m,'{trial_care}',marker||jsonb_build_object('evaluated_at',clock_timestamp()));
  end if;
 elsif p_decision->>'status'='eligible' and p_decision->'source' is not null then m:=m-'trial_care';
 end if;
 if p_decision->'source' is not null and p_decision->'source'<>'null'::jsonb then
  m:=jsonb_set(m,'{trial_care_source}',p_decision->'source');
 end if;
 return m;
end $function$

CREATE OR REPLACE FUNCTION private.crm_reconcile_trial_care_page_v1(p_customer_id bigint, p_limit integer, p_after_id bigint DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare r record; d jsonb; meta jsonb; evaluated integer:=0; suppressed integer:=0; review_count integer:=0; eligible integer:=0; last_id bigint:=p_after_id; more boolean;
begin
 -- Nonblocking lock avoids purchase-row/customer lock inversion. A busy customer
 -- stays queued; no purchase transaction is rolled back for reconciliation.
 if p_customer_id is not null and not pg_try_advisory_xact_lock(hashtextextended('crm_trial_care:'||p_customer_id,0)) then
  return jsonb_build_object('status','busy','evaluated',0,'suppressed',0,'needs_review',0,'eligible',0,'has_more',true,'next_after_id',p_after_id);
 end if;
 for r in select c.* from public.aka_crm c where (p_customer_id is null or c.customer_id=p_customer_id)
  and c.id>p_after_id and c.cskh_completed_date is null and private.crm_trial_care_candidate_v1(to_jsonb(c))
  order by c.id limit greatest(1,least(coalesce(p_limit,200),10000)) for update nowait
 loop
  d:=public.crm_trial_care_decision_v1(to_jsonb(r)); meta:=private.crm_trial_care_metadata_v1(r.gen_meta,d);
  if meta is distinct from r.gen_meta then update public.aka_crm set gen_meta=meta where id=r.id; end if;
  evaluated:=evaluated+1; last_id:=r.id;
  suppressed:=suppressed+case when d->>'status'='purchased' then 1 else 0 end;
  review_count:=review_count+case when d->>'status'='needs_review' then 1 else 0 end;
  eligible:=eligible+case when d->>'status'='eligible' then 1 else 0 end;
 end loop;
 select exists(select 1 from public.aka_crm c where (p_customer_id is null or c.customer_id=p_customer_id)
  and c.id>last_id and c.cskh_completed_date is null and private.crm_trial_care_candidate_v1(to_jsonb(c))) into more;
 return jsonb_build_object('status','ok','evaluated',evaluated,'suppressed',suppressed,'needs_review',review_count,'eligible',eligible,'has_more',more,'next_after_id',last_id);
exception when lock_not_available then
 -- Roll the whole page back, including its cursor. Never skip a locked row and
 -- accidentally acknowledge the queue before that row has been reconciled.
 return jsonb_build_object('status','busy','evaluated',0,'suppressed',0,'needs_review',0,'eligible',0,'has_more',true,'next_after_id',p_after_id);
end $function$

CREATE OR REPLACE FUNCTION private.campaign_log_legacy(p_campaign_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'public'
 SET plan_cache_mode TO 'force_custom_plan'
AS $function$
DECLARE r record; v_entries text[]:='{}'; v_bytes integer:=0; v_count integer:=0;
 v_truncated boolean:=false; v_updated timestamptz;
BEGIN
 -- Stop the index cursor once the legacy byte budget is full; never materialize
 -- thousands of large entries merely to return a 256 KiB compatibility tail.
 FOR r IN SELECT id,log,created_at FROM public.auto_campaign_logs WHERE campaign_id=p_campaign_id ORDER BY id DESC LIMIT 2001 LOOP
  IF v_updated IS NULL THEN v_updated:=r.created_at; END IF;
  IF v_count>=2000 OR v_bytes+octet_length(r.log)+1>262000 THEN v_truncated:=true; EXIT; END IF;
  v_entries:=array_append(v_entries,r.log); v_bytes:=v_bytes+octet_length(r.log)+1; v_count:=v_count+1;
 END LOOP;
 RETURN jsonb_build_object('id',p_campaign_id,'log',
  CASE WHEN v_truncated THEN '--- Chỉ hiển thị lịch sử chạy gần nhất; dùng ứng dụng mới để tải lịch sử cũ hơn ---'||E'\n' ELSE '' END
  ||coalesce((SELECT string_agg(x,E'\n' ORDER BY n DESC) FROM unnest(v_entries) WITH ORDINALITY e(x,n)),''),
  'updatedAt',v_updated);
END $function$

CREATE OR REPLACE FUNCTION private.campaign_log_page(p_campaign_id bigint, p_options jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'public'
 SET plan_cache_mode TO 'force_custom_plan'
AS $function$
DECLARE
 v_limit integer:=100; v_before bigint; v_after bigint; v_upper bigint; v_rows jsonb; v_more boolean; v_cursor text;
BEGIN
 IF p_options IS NULL OR jsonb_typeof(p_options)<>'object' THEN RAISE EXCEPTION 'Invalid campaign log options'; END IF;
 IF p_options->>'legacy'='true' THEN RETURN private.campaign_log_legacy(p_campaign_id); END IF;
 IF p_options ? 'limit' THEN
  IF coalesce(p_options->>'limit','') !~ '^[0-9]{1,3}$' THEN RAISE EXCEPTION 'Invalid campaign log limit'; END IF;
  v_limit:=(p_options->>'limit')::integer;
 END IF;
 IF v_limit<1 OR v_limit>500 THEN RAISE EXCEPTION 'Invalid campaign log limit'; END IF;
 IF p_options ? 'beforeId' THEN
  IF coalesce(p_options->>'beforeId','') !~ '^[1-9][0-9]{0,18}$' THEN RAISE EXCEPTION 'Invalid before cursor'; END IF;
  v_before:=(p_options->>'beforeId')::bigint;
 END IF;
 IF p_options ? 'afterId' THEN
  IF coalesce(p_options->>'afterId','') !~ '^(0|[1-9][0-9]{0,18})$' THEN RAISE EXCEPTION 'Invalid after cursor'; END IF;
  v_after:=(p_options->>'afterId')::bigint;
 END IF;
 IF v_before IS NOT NULL AND v_after IS NOT NULL THEN RAISE EXCEPTION 'Conflicting log cursors'; END IF;
 IF p_options ? 'throughId' THEN
  IF v_after IS NULL OR coalesce(p_options->>'throughId','') !~ '^(0|[1-9][0-9]{0,18})$' THEN RAISE EXCEPTION 'Invalid upper cursor'; END IF;
  v_upper:=(p_options->>'throughId')::bigint;
 END IF;
 IF v_after IS NOT NULL THEN
  IF v_upper IS NULL THEN SELECT coalesce((SELECT id FROM public.auto_campaign_logs WHERE campaign_id=p_campaign_id ORDER BY id DESC LIMIT 1),0) INTO v_upper; END IF;
  WITH candidates AS MATERIALIZED (
   SELECT id,log,created_at FROM public.auto_campaign_logs
   WHERE campaign_id=p_campaign_id AND id>v_after AND id<=v_upper ORDER BY id ASC LIMIT v_limit+1
  ), page AS (SELECT * FROM candidates ORDER BY id ASC LIMIT v_limit)
  SELECT coalesce((SELECT jsonb_agg(jsonb_build_object('id',id::text,'log',log,'createdAt',created_at) ORDER BY id) FROM page),'[]'),
   (SELECT count(*)>v_limit FROM candidates),(SELECT max(id)::text FROM page)
  INTO v_rows,v_more,v_cursor;
 ELSE
  WITH candidates AS MATERIALIZED (
   SELECT id,log,created_at FROM public.auto_campaign_logs
   -- Keep the cursor in the index condition. Custom plans avoid a generic
   -- estimate choosing the global PK for a campaign with very sparse history.
   WHERE campaign_id=p_campaign_id AND id<=coalesce(v_before-1,9223372036854775807::bigint) ORDER BY id DESC LIMIT v_limit+1
  ), page AS (SELECT * FROM candidates ORDER BY id DESC LIMIT v_limit)
  SELECT coalesce((SELECT jsonb_agg(jsonb_build_object('id',id::text,'log',log,'createdAt',created_at) ORDER BY id DESC) FROM page),'[]'),
   (SELECT count(*)>v_limit FROM candidates),(SELECT min(id)::text FROM page)
  INTO v_rows,v_more,v_cursor;
 END IF;
 RETURN jsonb_build_object('campaignId',p_campaign_id,'items',v_rows,'hasMore',v_more,'nextCursor',v_cursor,'throughId',v_upper::text);
END $function$

CREATE OR REPLACE FUNCTION private.aka_order_owner_state(o aka_order)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare owner_id bigint; n bigint; sql_owner bigint; chat_owner bigint; native boolean;
begin
  native := o.source_system = 'org_product' or o.org_organization_product_id is not null;
  if coalesce(native,false) then
    select g.staff_id_owner into owner_id from public.org_organization g
      where g.id = o.organization_id;
    if owner_id is null then return jsonb_build_object('issue','organization_owner_missing'); end if;
  elsif o.org_staff_id is not null then owner_id := o.org_staff_id;
  else
    if o.staff_manage_id_old is not null then
      select count(*),min(s.id) into n,sql_owner from public.org_staff s
        where s.organization_id=1 and s.sql_staff_id=o.staff_manage_id_old and s.deleted_at is null;
      if n<>1 then return jsonb_build_object('issue','sql_owner_ambiguous'); end if;
    end if;
    if o.staff_id is not null then
      select count(*),min(s.id) into n,chat_owner from public.org_staff s
        where s.organization_id=1 and s.chat_staff_id=o.staff_id and s.deleted_at is null;
      if n<>1 then return jsonb_build_object('issue','chat_owner_ambiguous'); end if;
    end if;
    if sql_owner is not null and chat_owner is not null and sql_owner<>chat_owner then
      return jsonb_build_object('issue','source_owners_conflict');
    end if;
    owner_id := coalesce(sql_owner,chat_owner);
  end if;
  if owner_id is not null and not exists(select 1 from public.org_staff where id=owner_id and organization_id=1 and deleted_at is null) then
    return jsonb_build_object('issue','owner_missing');
  end if;
  return jsonb_build_object('ownerId',owner_id,'issue',null);
end $function$

CREATE OR REPLACE FUNCTION private.copy_shared_group(p_staff_id bigint, p_organization_id bigint, p_kind text, p_group_id bigint, p_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_request text:=p_data->>'requestId';
  v_hash text:=md5(p_data::text);
  v_prior private.group_copy_requests%ROWTYPE;
  v_access jsonb;
  v_source public.auto_account_contact_groups%ROWTYPE;
  v_target public.auto_account_contact_groups%ROWTYPE;
  v_content_group public.auto_content_groups%ROWTYPE;
  v_target_id bigint:=NULLIF(p_data->>'targetGroupId','')::bigint;
  v_template_id bigint:=NULLIF(p_data->>'templateId','')::bigint;
  v_member_ids bigint[];
  v_contact_id bigint;
  v_member_id bigint;
  v_count integer:=0;
  v_row record;
  v_revision bigint;
  v_result jsonb;
  v_base_name text;
  v_copy_name text;
  v_name_attempt integer;
  v_inserted_template_id bigint;
BEGIN
  IF v_request IS NULL OR length(v_request) NOT BETWEEN 1 AND 500 THEN RAISE EXCEPTION 'invalid_group_copy_request'; END IF;
  IF p_kind='data' THEN
    PERFORM id FROM public.auto_account_contact_groups WHERE id IN (p_group_id,v_target_id) ORDER BY id FOR UPDATE;
  ELSE
    -- Copies into the same staff library allocate names in one transaction.
    -- Take this before group locks so overlapping multi-template copies cannot
    -- wait on each other's unique names in opposite source-template orders.
    PERFORM pg_advisory_xact_lock(hashtextextended('group-sharing-content-copy:'||p_staff_id::text,0));
    PERFORM id FROM public.auto_content_groups WHERE id IN (p_group_id,v_target_id) ORDER BY id FOR UPDATE;
  END IF;
  v_access:=private.group_access(p_kind,p_group_id,p_staff_id,p_organization_id);
  IF v_access IS NULL THEN RAISE EXCEPTION 'group_sharing_access_denied'; END IF;
  IF v_target_id IS NOT NULL AND NOT COALESCE((private.group_access(p_kind,v_target_id,p_staff_id,p_organization_id)->>'canManage')::boolean,false)
    THEN RAISE EXCEPTION 'group_sharing_owner_required'; END IF;
  IF v_target_id=p_group_id THEN RAISE EXCEPTION 'invalid_group_copy_target'; END IF;
  INSERT INTO private.group_copy_requests(staff_id,organization_id,request_id,request_hash)
    VALUES(p_staff_id,p_organization_id,v_request,v_hash) ON CONFLICT DO NOTHING;
  SELECT * INTO v_prior FROM private.group_copy_requests WHERE staff_id=p_staff_id AND organization_id=p_organization_id AND request_id=v_request FOR UPDATE;
  IF v_prior.request_hash<>v_hash THEN RAISE EXCEPTION 'data_group_request_id_conflict'; END IF;
  IF v_prior.result IS NOT NULL THEN RETURN v_prior.result; END IF;
  IF p_kind='data' THEN
    SELECT * INTO v_source FROM public.auto_account_contact_groups WHERE id=p_group_id;
    IF v_target_id IS NULL THEN
      INSERT INTO public.auto_account_contact_groups(name,color,sort_order,purpose,staff_id,organization_id,data_type_category_item_id,dataset_sync_mode,is_delete)
        VALUES(COALESCE(NULLIF(btrim(p_data->>'name'),''),v_source.name||' - Bản sao'),v_source.color,0,'data_group',p_staff_id,p_organization_id,v_source.data_type_category_item_id,'manual',false)
        RETURNING id INTO v_target_id;
    END IF;
    SELECT * INTO v_target FROM public.auto_account_contact_groups WHERE id=v_target_id;
    IF v_target.bound_zalo_account_id IS NOT NULL THEN RAISE EXCEPTION 'data_group_bound_source_unknown'; END IF;
    IF v_target.data_type_category_item_id IS NOT NULL AND v_target.data_type_category_item_id IS DISTINCT FROM v_source.data_type_category_item_id
      THEN RAISE EXCEPTION 'data_group_ingest_semantic_type_mismatch'; END IF;
    IF jsonb_typeof(p_data->'membershipIds')='array' THEN
      SELECT COALESCE(array_agg(DISTINCT x::bigint),'{}'::bigint[]) INTO v_member_ids FROM jsonb_array_elements_text(p_data->'membershipIds') x;
      IF EXISTS(SELECT 1 FROM unnest(v_member_ids) requested(id) WHERE NOT EXISTS(
        SELECT 1 FROM public.auto_account_contact_group_members m JOIN public.auto_account_contacts c ON c.id=m.contact_id
        WHERE m.id=requested.id AND m.group_id=p_group_id AND NOT m.is_delete AND NOT COALESCE(c.is_delete,false)
          AND c.staff_id=v_source.staff_id AND c.organization_id=p_organization_id))
        THEN RAISE EXCEPTION 'invalid_group_copy_members'; END IF;
    END IF;
    UPDATE public.auto_account_contact_groups SET revision=revision+1 WHERE id=v_target_id RETURNING revision INTO v_revision;
    FOR v_row IN SELECT c.*,COALESCE(o.data_type_category_item_id,v_source.data_type_category_item_id) copied_type
      FROM public.auto_account_contact_group_members m JOIN public.auto_account_contacts c ON c.id=m.contact_id
      LEFT JOIN public.auto_account_contact_group_member_origins o ON o.id=m.primary_origin_id AND o.is_current
      WHERE m.group_id=p_group_id AND NOT m.is_delete AND NOT COALESCE(c.is_delete,false)
        AND c.staff_id=v_source.staff_id AND c.organization_id=p_organization_id
        AND (v_member_ids IS NULL OR m.id=ANY(v_member_ids)) ORDER BY m.id
    LOOP
      -- Independent accountless records: never copy account permissions, tags, relationship flags or raw extra_data.
      INSERT INTO public.auto_account_contacts(staff_id,organization_id,account_id,contact_type,flatform_type,name,uid,url,phone,email,extra_data,is_delete)
        VALUES(p_staff_id,p_organization_id,NULL,v_row.contact_type,v_row.flatform_type,v_row.name,v_row.uid,v_row.url,v_row.phone,v_row.email,
          jsonb_strip_nulls(jsonb_build_object('info1',v_row.extra_data->'info1','info2',v_row.extra_data->'info2',
            'info3',v_row.extra_data->'info3','info4',v_row.extra_data->'info4','info5',v_row.extra_data->'info5')),false)
        RETURNING id INTO v_contact_id;
      INSERT INTO public.auto_account_contact_group_members(group_id,contact_id,change_revision,is_delete)
        VALUES(v_target_id,v_contact_id,v_revision,false) RETURNING id INTO v_member_id;
      INSERT INTO public.auto_account_contact_group_member_origins(membership_id,kind,source_name_snapshot,data_type_category_item_id,is_current)
        VALUES(v_member_id,'manual','Bản sao: '||v_source.name,v_row.copied_type,true);
      -- Preserve normal intake for the recipient's existing target group.
      FOR v_result IN SELECT public.aka_agent_internal_route_data_group_member(s.id,v_member_id,NULL,v_revision)
        FROM public.auto_campaign_data_group_sources s WHERE s.group_id=v_target_id AND s.status IN ('active','baselining') ORDER BY s.campaign_id
      LOOP NULL; END LOOP;
      v_count:=v_count+1;
    END LOOP;
  ELSE
    SELECT * INTO v_content_group FROM public.auto_content_groups WHERE id=p_group_id;
    IF NOT v_content_group.is_active AND (v_access->>'role')='shared' THEN RAISE EXCEPTION 'group_sharing_access_denied'; END IF;
    IF v_template_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.auto_content_templates
      WHERE id=v_template_id AND group_id=p_group_id AND staff_id=v_content_group.staff_id AND organization_id=p_organization_id AND NOT is_delete)
      THEN RAISE EXCEPTION 'invalid_group_copy_template'; END IF;
    IF v_target_id IS NULL THEN
      v_base_name:=COALESCE(NULLIF(btrim(p_data->>'name'),''),v_content_group.name||' - Bản sao');
      v_copy_name:=v_base_name;
      v_name_attempt:=1;
      LOOP
        -- Let the existing unique index arbitrate concurrent copies/ordinary
        -- creates as well as case-insensitive, trimmed-name collisions.
        INSERT INTO public.auto_content_groups(name,description,stt,is_active,staff_id,organization_id,is_delete)
          VALUES(v_copy_name,v_content_group.description,100,true,p_staff_id,p_organization_id,false)
          ON CONFLICT (staff_id, (lower(btrim(name)))) WHERE staff_id IS NOT NULL AND is_delete=false
          DO NOTHING RETURNING id INTO v_target_id;
        EXIT WHEN v_target_id IS NOT NULL;
        v_name_attempt:=v_name_attempt+1;
        v_copy_name:=v_base_name||' ('||v_name_attempt||')';
      END LOOP;
    END IF;
    IF NOT EXISTS(SELECT 1 FROM public.auto_content_groups WHERE id=v_target_id AND is_active) THEN RAISE EXCEPTION 'invalid_group_copy_target'; END IF;
    FOR v_row IN SELECT * FROM public.auto_content_templates
      WHERE group_id=p_group_id AND staff_id=v_content_group.staff_id AND organization_id=p_organization_id
        AND NOT is_delete AND (v_template_id IS NULL OR id=v_template_id) ORDER BY id
    LOOP
      v_copy_name:=v_row.name;
      v_base_name:=v_row.name||' - Bản sao';
      v_name_attempt:=0;
      LOOP
        INSERT INTO public.auto_content_templates(name,content,group_id,content_type_id,image_urls,channels,channel_image_urls,base_content_html,staff_id,organization_id,is_delete)
          VALUES(v_copy_name,v_row.content,v_target_id,v_row.content_type_id,v_row.image_urls,v_row.channels,v_row.channel_image_urls,v_row.base_content_html,p_staff_id,p_organization_id,false)
          ON CONFLICT (staff_id, (lower(btrim(name)))) WHERE is_delete=false
          DO NOTHING RETURNING id INTO v_inserted_template_id;
        EXIT WHEN v_inserted_template_id IS NOT NULL;
        v_name_attempt:=v_name_attempt+1;
        v_copy_name:=v_base_name||CASE WHEN v_name_attempt=1 THEN '' ELSE ' ('||v_name_attempt||')' END;
      END LOOP;
      v_count:=v_count+1;
    END LOOP;
  END IF;
  v_result:=jsonb_build_object('groupId',v_target_id,'count',v_count);
  UPDATE private.group_copy_requests SET result=v_result WHERE staff_id=p_staff_id AND organization_id=p_organization_id AND request_id=v_request;
  RETURN v_result;
END;
$function$

CREATE OR REPLACE FUNCTION private.column_filter_source_match_v1(extra jsonb, query jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE source text:=nullif(btrim(query->>'source'),''); url text; key text; kind text; found boolean;
BEGIN
 url:=private.column_filter_fb_url_v1(query->>'sourcePostUrl','post');
 IF source IS NOT NULL AND url IS NOT NULL AND jsonb_typeof(extra->'sourcePostRefs')='array' AND EXISTS(SELECT 1 FROM jsonb_array_elements(extra->'sourcePostRefs') r WHERE nullif(btrim(r->>'source'),'') IS NOT NULL AND nullif(btrim(COALESCE(nullif(r->>'url',''),r->>'sourcePostUrl')),'') IS NOT NULL) THEN
  IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(extra->'sourcePostRefs') r WHERE btrim(r->>'source')=source AND private.column_filter_fb_url_v1(COALESCE(nullif(r->>'url',''),r->>'sourcePostUrl'),'post')=url) THEN RETURN false; END IF;
 ELSE
  IF source IS NOT NULL AND btrim(extra->>'source') IS DISTINCT FROM source AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements_text(CASE WHEN jsonb_typeof(extra->'sources')='array' THEN extra->'sources' ELSE '[]'::jsonb END) v WHERE btrim(v)=source) THEN RETURN false; END IF;
  IF url IS NOT NULL AND private.column_filter_fb_url_v1(extra->>'sourcePostUrl','post') IS DISTINCT FROM url AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements_text(CASE WHEN jsonb_typeof(extra->'sourcePostUrls')='array' THEN extra->'sourcePostUrls' ELSE '[]'::jsonb END) v WHERE private.column_filter_fb_url_v1(v,'post')=url) THEN RETURN false; END IF;
 END IF;
 FOREACH kind IN ARRAY ARRAY['profile','group'] LOOP
  key:=CASE kind WHEN 'profile' THEN 'sourceProfileUrl' ELSE 'sourceGroupUrl' END;url:=private.column_filter_fb_url_v1(query->>key,kind);
  IF url IS NOT NULL AND private.column_filter_fb_url_v1(extra->>key,kind) IS DISTINCT FROM url AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements_text(CASE WHEN jsonb_typeof(extra->(key||'s'))='array' THEN extra->(key||'s') ELSE '[]'::jsonb END) v WHERE private.column_filter_fb_url_v1(v,kind)=url) THEN RETURN false; END IF;
 END LOOP;
 RETURN true;
END $function$

CREATE OR REPLACE FUNCTION private.column_filter_phone_v1(value text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE STRICT
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE digits text; mapped text; prefixes constant jsonb:='{"0162":"032","0163":"033","0164":"034","0165":"035","0166":"036","0167":"037","0168":"038","0169":"039","0120":"070","0121":"079","0122":"077","0126":"076","0128":"078","0123":"083","0124":"084","0125":"085","0127":"081","0129":"082","0186":"056","0188":"058","0199":"059"}';
BEGIN
 IF btrim(value) ~* '^[+-]?\d+(\.\d+)?e[+-]?\d+$' AND length(value)<40 THEN BEGIN value:=trunc(value::numeric)::text; EXCEPTION WHEN numeric_value_out_of_range THEN RETURN NULL; END; END IF;
 digits:=regexp_replace(value,'\D','','g');
 IF left(digits,4)='0084' AND length(digits)>=13 THEN digits:='0'||substr(digits,5);
 ELSIF left(digits,2)='84' AND length(digits)>=11 THEN digits:='0'||substr(digits,3); END IF;
 IF length(digits)=9 AND digits ~ '^[35789]' THEN digits:='0'||digits; END IF;
 IF length(digits)=10 THEN mapped:=prefixes->>('0'||left(digits,3)); IF mapped IS NOT NULL THEN digits:=mapped||substr(digits,4); END IF;
 ELSIF length(digits)=11 THEN mapped:=prefixes->>left(digits,4); IF mapped IS NOT NULL THEN digits:=mapped||substr(digits,5); END IF; END IF;
 RETURN CASE WHEN digits ~ '^0[35789]\d{8}$' THEN digits END;
END $function$

CREATE OR REPLACE FUNCTION private.column_filter_tag_values_v1(value jsonb)
 RETURNS text[]
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE item jsonb; result text[]:='{}'; id text;
BEGIN
 IF jsonb_typeof(value)='array' THEN FOR item IN SELECT jsonb_array_elements(value) LOOP result:=result||private.column_filter_tag_values_v1(item); END LOOP; RETURN result;
 ELSIF jsonb_typeof(value)='object' THEN id:=private.column_filter_text_v1(value->>'id',value->>'labelId',value->>'label_id',value->>'tagId',value->>'tag_id');
 ELSE id:=nullif(btrim(value#>>'{}'),''); END IF;
 RETURN CASE WHEN id IS NULL THEN '{}'::text[] ELSE ARRAY[id] END;
END $function$

CREATE OR REPLACE FUNCTION private.column_filter_uri_decode_v1(value text, form boolean DEFAULT false)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE STRICT
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE result bytea:=''::bytea; i integer:=1; ch text;
BEGIN
 WHILE i<=length(value) LOOP
  ch:=substr(value,i,1);
  IF ch='%' THEN
   IF substr(value,i+1,2) !~ '^[0-9a-fA-F]{2}$' THEN RAISE EXCEPTION 'invalid_uri'; END IF;
   result:=result||decode(substr(value,i+1,2),'hex');i:=i+3;
  ELSE result:=result||convert_to(CASE WHEN form AND ch='+' THEN ' ' ELSE ch END,'UTF8');i:=i+1;END IF;
 END LOOP;
 RETURN convert_from(result,'UTF8');
END $function$

CREATE OR REPLACE FUNCTION private.column_filter_uri_encode_v1(value text, form boolean DEFAULT false)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE STRICT
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE result text:=''; bytes bytea:=convert_to(value,'UTF8'); b integer; i integer;
BEGIN
 FOR i IN 0..length(bytes)-1 LOOP
  b:=get_byte(bytes,i);
  IF (b BETWEEN 65 AND 90) OR (b BETWEEN 97 AND 122) OR (b BETWEEN 48 AND 57) OR b IN (45,46,95,42) OR (NOT form AND b IN (33,39,40,41,126)) THEN result:=result||chr(b);
  ELSIF form AND b=32 THEN result:=result||'+';
  ELSE result:=result||'%'||upper(lpad(to_hex(b),2,'0'));END IF;
 END LOOP;
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION private.column_filter_fb_url_v1(value text, kind text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE raw text:=btrim(value); url text; host text; protocol text; path text; query text; result text; pair text; key text; val text; parts text[]; i integer; removed boolean:=false;
BEGIN
 IF raw IS NULL OR raw='' THEN RETURN NULL; END IF;
 IF kind='profile' THEN raw:=regexp_replace(raw,'^@+',''); END IF;
 IF kind IN ('profile','group') AND raw !~* '(facebook\.com|fb\.com)' THEN
  result:=raw;
  IF kind='group' THEN
   result:=btrim(raw,'/');parts:=array_remove(string_to_array(result,'/'),'');
   IF lower(parts[1])='groups' AND parts[2] IS NOT NULL THEN result:=parts[2]; END IF;
  END IF;
  RETURN CASE WHEN result ~ '^[a-zA-Z0-9._-]+$' THEN lower('https://www.facebook.com/'||CASE WHEN kind='group' THEN 'groups/' ELSE '' END||result) END;
 END IF;
 url:=CASE WHEN raw ~* '^https?://' THEN raw ELSE 'https://'||raw END;
 protocol:=lower(split_part(url,'://',1));host:=lower(substring(url from '^https?://([^/?#]+)'));
 -- WHATWG URL removes default ports. Nondefault ports matter only for post URLs.
 host:=regexp_replace(host,CASE protocol WHEN 'http' THEN ':80$' ELSE ':443$' END,'');
 IF host ~* '@' THEN host:=regexp_replace(host,'^.*@',''); END IF;
 FOREACH key IN ARRAY CASE WHEN kind='post' THEN ARRAY['www','web','m'] ELSE ARRAY['www','web','m','mobile','mbasic'] END LOOP host:=regexp_replace(host,'^'||key||'\.','','i'); END LOOP;
 IF split_part(host,':',1) NOT IN ('facebook.com','fb.com') THEN RETURN NULL; END IF;
 path:=regexp_replace(url,'^https?://[^/?#]+','','i');path:=split_part(path,'#',1);query:=CASE WHEN strpos(path,'?')>0 THEN substr(path,strpos(path,'?')+1) ELSE '' END;path:=split_part(path,'?',1);
 IF path='' THEN path:='/'; END IF;
 IF kind='group' THEN
  parts:=array_remove(string_to_array(path,'/'),'');result:=NULL;
  FOR i IN 1..COALESCE(cardinality(parts),0) LOOP IF lower(parts[i])='groups' THEN result:=parts[i+1];EXIT;END IF;END LOOP;
  result:=btrim(private.column_filter_uri_decode_v1(result));
  RETURN CASE WHEN result ~ '^[a-zA-Z0-9._-]+$' THEN lower('https://www.facebook.com/groups/'||result) END;
 ELSIF kind='profile' THEN
  IF path='/profile.php' THEN
   FOREACH pair IN ARRAY string_to_array(query,'&') LOOP
    IF private.column_filter_uri_decode_v1(split_part(pair,'=',1),true)='id' THEN
     result:=btrim(private.column_filter_uri_decode_v1(CASE WHEN strpos(pair,'=')>0 THEN substr(pair,strpos(pair,'=')+1) ELSE '' END,true));EXIT;
    END IF;
   END LOOP;
   RETURN CASE WHEN nullif(result,'') IS NOT NULL THEN lower('https://www.facebook.com/profile.php?id='||private.column_filter_uri_encode_v1(result)) END;
  END IF;
  parts:=array_remove(string_to_array(path,'/'),'');
  WHILE lower(parts[cardinality(parts)])='friends' LOOP parts:=parts[1:cardinality(parts)-1];END LOOP;
  IF cardinality(parts)<>1 THEN RETURN NULL;END IF;
  result:=btrim(private.column_filter_uri_decode_v1(parts[1]));
  RETURN CASE WHEN result ~ '^[a-zA-Z0-9._-]+$' THEN lower('https://www.facebook.com/'||result) END;
 END IF;
 result:='';
 FOREACH pair IN ARRAY string_to_array(query,'&') LOOP
  IF pair='' THEN CONTINUE;END IF;
  key:=private.column_filter_uri_decode_v1(split_part(pair,'=',1),true);
  IF key ~ '^(__|mibextid$|ref$|locale$|comment_id$|reply_comment_id$)' THEN removed:=true;CONTINUE;END IF;
  val:=private.column_filter_uri_decode_v1(CASE WHEN strpos(pair,'=')>0 THEN substr(pair,strpos(pair,'=')+1) ELSE '' END,true);
  result:=result||CASE WHEN result='' THEN '' ELSE '&' END||private.column_filter_uri_encode_v1(key,true)||'='||private.column_filter_uri_encode_v1(val,true);
 END LOOP;
 IF removed THEN query:=result;END IF;
 RETURN lower(rtrim(protocol||'://www.facebook.com'||CASE WHEN strpos(host,':')>0 THEN ':'||split_part(host,':',2) ELSE '' END||path||CASE WHEN query='' THEN '' ELSE '?'||query END,'/'));
EXCEPTION WHEN data_exception OR raise_exception THEN RETURN lower(rtrim(raw,'/'));
END $function$
